        ConfigOption(key: "fexfail", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml787: deterministic call-ret allocation failure injection. Documents/madeira-fexfail.txt holds \"reserve:N\" or \"commit:N\". The containment path it exercises only occurs naturally when a title exhausts the emulator's address band, and onl...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
