        ConfigOption(key: "mono-suspend", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml713: Mono suspend-policy A/B. Documents/madeira-mono-suspend.txt containing \"preemptive\" (or \"coop\"/\"hybrid\") sets MONO_THREADS_SUSPEND for wine-mono, so the comparison needs no rebuild. EXPERIMENT, NOT A FIX, and deliberately not a de...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "real-suspend", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "this session, or nil to leave it unset. Without it a Wine SuspendThread only snapshots the target's registers while the thread keeps running (ml730, build/wineserver/mach_ios.c). A Unity IL2CPP game's garbage collector suspends every thr...", choices: [], sources: ["app/Madeira/LibraryBCD.swift"]),
        ConfigOption(key: "remote", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml762: remote Metal backend. Documents/madeira-remote.txt holds \"<host-ip> <token>\" and routes winemetal to a Metal daemon on that host instead of the local device. The mode is decided ONCE per process: flipping it later would leave hand...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "remote-batch", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml821: coalesced remote messages. Documents/madeira-remote-batch.txt == \"1\" makes the pre-submission flush send many buffer ranges per round trip and drains autorelease pools in one call. It is OPT-IN because the measurement it is meant ...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "shadow", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml760: shadow-pack mode. Documents/madeira-shadow.txt == \"1\" packs and validates every real render batch into the remote wire format, then discards it and renders locally as normal. Exercises the packer against live traffic where being w...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "swap-canary", title: "", kind: .bool, defaultValue: "0", category: "App & front end", note: "ml1095: madeira.cfg swap-canary = 1", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "swap-min-kb", title: "", kind: .int, defaultValue: "0", category: "App & front end", note: "madeira-bcd: swap-min-kb (madeira.cfg or the game's config) lowers the tier's 8 MB eligibility floor. Upstream's virtual_ios.c reads MADEIRA_SWAP_MIN_KB only in its \"blocks\" coverage, so swap-min-kb selects that; an env.MADEIRA_SWAP_COVE...", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "tf-trace", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml734: Theorafile call tracer. Documents/madeira-tf-trace.txt == \"1\" redirects libtheorafile's tf_* exports through wrappers in tftrace-x64.dll that call the original and report the RETURN value. The intro decodes and plays, the stream r...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "usd-time", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml731: Windows shared-data clock A/B. Documents/madeira-usd-time.txt == \"1\" makes wineserver update KUSER_SHARED_DATA's SystemTime, InterruptTime and TickCount again. Without it those stay frozen at their init values, so GetTickCount/Env...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "valley-args", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "AncientGame-Win64-Shipping.exe ValleyoftheAncient and nothing else, which is why the launcher is skipped here. Flags come from Documents/madeira-valley-args.txt so a UE switch can be tried without rebuilding and reinstalling. The default...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "wx", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml694: W^X A/B switch. Documents/madeira-wx.txt containing \"0\" disables page demotion for the SAME binary, so the on/off comparison needs one rebuild, not two. The previous gate read container paths that can never exist, so it silently f...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "wxprobe", title: "", kind: .text, defaultValue: "", category: "App & front end", note: "ml748: W^X A/B probe. Documents/madeira-wxprobe.txt == \"1\" runs it. Loading xtajit64.dll faults writing its .rdata on the jailbroken research VM and not on this phone, with CS_DEBUGGED live in both, so attachment is not the variable. Eit...", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_DOWNMIX", title: "Mix surround sound down to stereo", kind: .bool, defaultValue: "1", category: "Audio", note: "On by default: a game that plays 5.1 or 7.1 sound has every channel folded into the two speakers, so voices (in the centre channel), bass and the rear channels are heard. Off keeps only the front left and right channels, as Madeira did before, which loses most dialogue in a surround game. Applies at the next game start.", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_GAIN", title: "Game volume at the output (%)", kind: .int, defaultValue: "100", category: "Audio", note: "Percent of the game's level, 10-200; unset or 100 leaves it unchanged. Read once, at the first audio endpoint. Set it in the game's own file.", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_IO_US", title: "", kind: .text, defaultValue: "", category: "Audio", note: "The shared-mode engine period, in 100 ns units. A client that keeps one period queued (IAudioClient3) must cover a whole RemoteIO slice, or every render callback empties its queue and plays silence for the rest: at least two slices of th...", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_LEAD_MS", title: "Sound buffer", kind: .choice, defaultValue: "", category: "Audio", note: "How much sound Madeira keeps queued ahead of the speaker (10-500 ms, default 60). If a game's sound crackles or sounds scratchy, a larger buffer usually clears it, at the cost of sound lagging slightly behind the picture: Black Ops II's Zombies crackled at 60 ms and was clean at 150. A game's own config can set it for that game alone. Applies at the next game start.", choices: [("", "60 ms (default)"), ("100", "100 ms"), ("150", "150 ms"), ("200", "200 ms"), ("300", "300 ms")], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_PERIOD_MS", title: "", kind: .text, defaultValue: "", category: "Audio", note: "The shared-mode engine period, in 100 ns units. A client that keeps one period queued (IAudioClient3) must cover a whole RemoteIO slice, or every render callback empties its queue and plays silence for the rest: at least two slices of th...", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_RESUME", title: "Bring game audio back after an interruption", kind: .bool, defaultValue: "0", category: "Audio", note: "Default off: after a call, Siri, an alarm or a suspension the sound stays off until the game restarts. 1: the audio session is activated again and the output restarted; while iOS holds it stopped the game's audio clock keeps running. Logged as [audio] interruption began / ended. Read when the session starts.", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUDIO_SPATIAL", title: "", kind: .text, defaultValue: "", category: "Audio", note: "0: no spatial audio (a game falls back to a plain stream); unset or 1: Wine's spatial audio, as before", choices: [], sources: ["build/ntdll-unix/audio_null_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CONTROL_PRESETS", title: "", kind: .bool, defaultValue: "1", category: "Controllers", note: "Owns madeira-control-presets.json and applies layouts to TouchControlsModel. Main thread only, like the overlay that drives it.", choices: [], sources: ["app/Madeira/TouchControlPresets.swift"]),
        ConfigOption(key: "env.MADEIRA_DINPUT_PAD", title: "DirectInput joystick from the host gamepad", kind: .text, defaultValue: "", category: "Controllers", note: "Default OFF: see \"OPT-IN\" at the top of this file. MADEIRA_DINPUT_PAD=1 turns the DirectInput view on for DirectInput-only games.", choices: [], sources: ["wine/dlls/dinput/joystick_ios.c", "app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_DINPUT_TRACE", title: "", kind: .text, defaultValue: "", category: "Controllers", note: "Opt-in (MADEIRA_DINPUT_TRACE=1) and limited by a PROCESS-wide call counter: the per-device millisecond limiter never engaged for a title that re-creates its device constantly, and 260,000 trace lines in one session cost more than the inp...", choices: [], sources: ["wine/dlls/dinput/joystick_ios.c"]),
        ConfigOption(key: "env.MADEIRA_HIDPAD", title: "", kind: .text, defaultValue: "", category: "Controllers", note: "Set by the app at session start from env.MADEIRA_PAD_MODE (dualsense or generic) for the wineserver and ntdll; not meant to be set by hand.", choices: [], sources: ["build/ntdll-unix/server_ios.c", "build/wineserver/hidpad_ios.c"]),
        ConfigOption(key: "env.MADEIRA_HIDPAD_AUTO_GENERIC", title: "HID mode: other pads as a generic HID gamepad", kind: .bool, defaultValue: "0", category: "Controllers", note: "1: with env.MADEIRA_PAD_MODE = hid, a pad that is not a PlayStation one becomes a generic HID gamepad and leaves XInput (the old behaviour). Off: it stays on XInput.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_HIDPAD_NAME", title: "", kind: .text, defaultValue: "", category: "Controllers", note: "Set by the app: the product string a generic HID gamepad reports (the physical pad's name).", choices: [], sources: ["build/wineserver/hidpad_ios.c"]),
        ConfigOption(key: "env.MADEIRA_HIDPAD_XINPUT", title: "HID mode: keep player 1 on XInput too", kind: .bool, defaultValue: "0", category: "Controllers", note: "1: with the HID controller on, player 1 also stays an XInput pad. Off by default, so a game that reads both APIs does not see the same pad twice.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PAD_MODE", title: "Controller API (player 1)", kind: .choice, defaultValue: "", category: "Controllers", note: "XInput (default): every controller is an Xbox pad. hid: player 1 becomes a HID game controller, a DualSense (054C:0CE6) when it is a PlayStation pad, and leaves XInput; any other pad stays on XInput. dualsense/generic force the identity. Read at session start; the game's own file wins.", choices: [("", "XInput (default)"), ("hid", "DirectInput / HID"), ("dualsense", "HID, always a DualSense"), ("generic", "HID, always a generic gamepad")], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PAD_OUTPUT", title: "Rumble, adaptive triggers and lightbar to the pad", kind: .choice, defaultValue: "", category: "Controllers", note: "On (default): XInput rumble plays on the controller (CoreHaptics), and in DualSense HID mode the game's output reports drive rumble, adaptive triggers (closest GameController mode), lightbar and player LEDs. hid: only the DualSense's; xinput: only XInput rumble; 0: none. Read at session start; the game's own file wins.", choices: [("", "On (default)"), ("hid", "DualSense output only"), ("xinput", "XInput rumble only"), ("0", "Off")], sources: ["app/Madeira/GamepadInput.swift", "app/Madeira/PadOutput.m"]),
        ConfigOption(key: "env.MADEIRA_WGI_HOST_PADS", title: "Controllers in Windows.Gaming.Input", kind: .bool, defaultValue: "0", category: "Controllers", note: "Default off. 1: each connected XInput controller (a paired pad or the touch controller) is also a Windows.Gaming.Input gamepad, an Xbox pad to the game, with rumble. For games that read their controller only that way (Horizon Zero Dawn); a game that also reads XInput could list it twice. Read when the game first asks for a gamepad.", choices: [], sources: ["wine/dlls/windows.gaming.input/provider.c"]),
        ConfigOption(key: "env.MADEIRA_XINPUT_BATTERY", title: "Controller battery level to XInput", kind: .bool, defaultValue: "1", category: "Controllers", note: "On (default): XInputGetBatteryInformation reports each pad's GameController battery (wired while charging, else a level) and XInputGetCapabilities flags a battery-powered pad as wireless. 0: an unknown battery, as before.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_XINPUT_ENABLE_FOREGROUND", title: "Ignore a stale XInput disable while the game is in front", kind: .bool, defaultValue: "1", category: "Controllers", note: "On (default): when a game has switched XInput off (XInputEnable(FALSE), usually on losing focus) but its window is in front, it still reads the pad; activation messages at startup can leave it off for good. 0: the pad reads at rest while disabled, as before. Read by win32u, so 32- and 64-bit games alike.", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_XINPUT_PROFILE_CHECK", title: "Re-read a controller's input profile", kind: .bool, defaultValue: "1", category: "Controllers", note: "ml2190: on (default): every 2 s the app checks each connected controller's extended-gamepad profile and, when GameController has replaced it (a remap or a mode change after the controller joined), reads the live one; the first 8 times the sticks leave rest the raw values are logged ([xinput] ml2190). 0: a slot keeps the profile its controller had when it joined, as before.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_XINPUT_SLOT0_RECONNECT", title: "Reconnected controller back to player 1", kind: .bool, defaultValue: "1", category: "Controllers", note: "On (default): when player 1's controller reconnects and GameController reports it as a new controller before the old one leaves, it is moved from the slot it landed in back to slot 0. 0: it stays where it landed, as before.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_BAND_CENSUS", title: "Log the 64 GB address band by piece", kind: .bool, defaultValue: "0", category: "Debugging / logs", note: "Default off. 1: about once a minute and when a large reserve fails, [band] lines say what each piece of [0x7000000000, 0x8000000000) uses (Social Club's pools and metadata, the furniture, the V8 and Oilpan cages, the FEX arena), the largest free gap, and whether Red Dead Redemption 2's 8960 MB reserve fits; 64 censuses at most. Logging only, changes no placement; read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EC_HOOK_TRACE", title: "Log code patches the emulated copy misses", kind: .bool, defaultValue: "0", category: "Debugging / logs", note: "Default off, logging only. 1 compares executable PE sections and their pool copies before sync, including x64 entry thunks. Separate budgets preserve later graphics-jump records after native startup rewrites. A difference alone does not prove an inline hook.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_IMAGE_PATCH_TRACE", title: "DLL code patch trace", kind: .bool, defaultValue: "0", category: "Debugging / logs", note: "1 logs up to 64 successful 1–16 byte executable-image protection requests and their PE/pool bytes. Read-only, owner-aware diagnostics; does not alter hooks or code.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LEAN_DIAG", title: "Lean diagnostics (no thread-suspending samplers)", kind: .bool, defaultValue: "0", category: "Debugging / logs", note: "1: the samplers that suspend threads stop ([thread-sample] bursts every 20 s, the guest RIP profile behind [rip-profile] and [cpu-split], [wprof]); the warmer's address-space walks ([phys-map], slot and window inventory) run every ~10 min instead of every minute, its zone check and allocation probe every minute instead of every 2 s; mprotect_exec's per-call ERR line is kept for the first 200 calls, then every 1000th. [xp], [xp-t], [xp-api] and [sync-census] keep their rates. Off (default): every diagnostic as before. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POWER_PROBE", title: "Log GPU and device power every 5 s", kind: .bool, defaultValue: "0", category: "Debugging / logs", note: "1: every 5 s a [power] line next to [xp]'s CPU energy: the GPU energy and time the driver charged to the app's coalition, the SoC's Energy Model counters (IOReport) and the battery's voltage and current (the whole device while unplugged), each source named unavailable once when the system gives nothing; and [power-t], the threads that used the most energy. Off (default): nothing is read. Needs the [xp] sampler. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "addr-scan", title: "Quicker GPU-address lookups", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. Finding the buffer behind a GPU address (every vertex buffer, index buffer and root descriptor a game records) walks back only over entries that can still reach the address, instead of over every buffer within the largest buffer's size of it (124 MB in Horizon Zero Dawn). The same buffer is found. 0: the old walk. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ags-rewrite", title: "D3D12 AMD AGS 64-bit atomics rewrite", kind: .text, defaultValue: "", category: "Direct3D 12", note: "ml1149: read once; madeira.cfg ags-rewrite = 0 turns the rewrite off.", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "async-present-ahead", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1121: bounded run-ahead. Present enqueues and returns; the application may start the next frame while the worker encodes this one, but no more than async-present-ahead presents (default 1) may be queued behind it.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "async-submit", title: "D3D12 asynchronous submission", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1120: asynchronous submission", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "attachless-split", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml910/ml913 madeira-bcd skin-check: before the pass, its captures are blits ml1311: madeira.cfg attachless-split = 1 gives every draw of an attachment-less pass its own encoder. On Apple GPUs the fragment work of consecutive draws in one...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "barrier-render", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1091; ml1098: madeira.cfg barrier-render = 1 closes the render pass too (Astra's conservative experiment)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-big", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "each) ate the whole budget in the first capture of a UE5 frame, so the G-buffer, lighting and final image were never written. Skip targets over 16 MB unless madeira.cfg capture-big = 1.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "ml1141: re-read every CAP, so the target can change between captures of one run", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs-indirect", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1141: re-read every CAP, so the target can change between captures of one run", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-cs-max", title: "", kind: .int, defaultValue: "12", category: "Direct3D 12", note: "ml1141: re-read every CAP, so the target can change between captures of one run", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-ps", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "ml1152: re-read every CAP, like capture-cs", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-raw", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "madeira-bcd: contact sheets", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "capture-uav", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira-bcd: contact sheets", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "cbv-snapshot", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix attempt: copy N bytes (1 = 4096) of every UPLOAD-heap root CBV at replay and bind the copy", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "clear-defer", title: "Clears wait for the pass that draws to their target", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "On by default. A whole render-target or depth-stencil clear becomes the clear the next render pass that draws to that target starts with: a clear no longer ends the pass in progress unless it is one of that pass's own targets, and needs no pass of its own (which wrote the whole target to memory and read it back later). A barrier or copy that names the cleared texture, or a pass or clear that uses it through another view, applies the clear first, so nothing sees it uncleared. 0: every clear ends the open pass and goes before the next pass on its own, as before. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "clear-rects", title: "Clear only the rectangles a game asks for", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: a render-target or depth-stencil clear with rectangles clears the whole view, as before. 1: only the rectangles are cleared, in a small pass of their own (as DXMT's D3D11 ClearView does); a rectangle that covers the view still clears it the fast way. Horizon Zero Dawn passes rectangles from its first gameplay frames.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "cs-dump", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "cs-split", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: 1 = every compute dispatch ends its compute encoder, so the next one waits on the encoder fence (FSR 3 black squares: ordering inside an encoder); 2 = only FidelityFX ('CS' entry) dispatches", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-bc-decode", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "1: decode BC uploads (no native BC), 0: raw copies", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-binding-tier", title: "Reported resource binding tier", kind: .int, defaultValue: "2", category: "Direct3D 12", note: "Default 2. 3: OPTIONS reports resource binding tier 3, as Apple's D3DMetal and vkd3d-proton do; a game can take another binding path for it. Anything else keeps tier 2. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-caps-log", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "2: format queries too", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-core-dll", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "1: load d3d12core.dll (Agility SDK layout); >1: also its D3D12SDKVersion", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-fl-12-1", title: "Claim feature level 12_1", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: 12_0 is the highest feature level the runtime claims. 1: 12_1, for a game that creates its device at 12_1 and stops when that is refused; OPTIONS still reports no conservative rasterization or ROVs. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-msaa8", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "1: report 8x MSAA (rendered at 4x)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-pso-cached-blob", title: "Cached blob of a pipeline", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: ID3D12PipelineState::GetCachedBlob fails (E_NOTIMPL), as before. 1: it answers a 16-byte blob, for an engine that treats the failure as fatal. Creating a pipeline never reads a blob handed back. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-raw-typed-views", title: "Raw buffer views readable as typed", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: raw and structured buffer views also carry a texture-buffer view (R32, or RG32/RGBA32 for a structured SRV whose stride allows it), as native drivers and vkd3d-proton do, so a shader that reads one as Buffer<T> gets the data instead of zeros (vertices at the origin). Costs one Metal texture object per such view.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-raytracing-tier", title: "Experiment: report a ray-tracing tier", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "Experiment, default 0. 10 or 11 reports DXR tier 1.0 or 1.1 in OPTIONS5 although the runtime has no ray tracing (its calls stay unimplemented stubs, logged once). Only for finding out whether a game's device check wants it.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-reserved-max-mb", title: "", kind: .int, defaultValue: "1024", category: "Direct3D 12", note: "d3d12-tiled-resources: largest reserved resource backed in full, in MB (larger ones are refused with E_OUTOFMEMORY)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-shader-pack", title: "D3D12 shader cache in two pack files", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Off by default: one file per converted shader in Documents/shadercache, as before. 1: the converter keeps its DXBC and DXIL cache entries in two append-only files (shadercache/pack/dxbc.mdpk, dxil.mdpk); loose entries of earlier runs move in as games use them. Off again, the packs are not read: what moved into them converts again. Bounds: DXIL as env.MADEIRA_D3D12_DXIL_CACHE_MB (512 MB), DXBC 2 GB; a full pack starts over. Read once per app start; the game's own file wins.", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "d3d12-sm-6-7", title: "Report shader model 6.7", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: SHADER_MODEL reports up to 6.6. 1: up to 6.7, for a game that requires it; the converter may still refuse a 6.7 shader, which fails its pipeline like any other conversion failure. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-tile-based", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: TileBasedRenderer FALSE, as desktop GPUs report", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-tiled-resources", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "opt-in: TiledResourcesTier 2, 40 VA bits per resource, R32G32B32 vertex formats, fully backed reserved resources", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-typed-uav-load", title: "D3D12 typed UAV loads (report support)", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1970: FORMAT_SUPPORT below already reports UAV_TYPED_LOAD for every uncompressed colour format (Metal read-write textures), but this option stays FALSE by default: reporting it can move an engine that already runs onto different render...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-wave-ops", title: "Report wave operations", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "On by default. 0: OPTIONS1 reports WaveOps FALSE, so a game with a fallback picks shaders without wave intrinsics (an A/B for the shader converter's wave code; Horizon Zero Dawn reads it). Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "d3d12-zero-extent-guard", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "1 (default): zero-size textures refused with E_INVALIDARG; 0: passed to Metal, which aborts", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "default-buffer-swap", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: 1 = large committed DEFAULT buffers (no UAV/RT/DS) on file-backed storage, 2 = UAV ones too; 0 = Metal-owned private memory (as before)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "default-buffer-swap-max-mb", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "default-buffer-swap moves buffers only while the moved total stays at or below this many MB; 0 = no limit", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "default-buffer-swap-mb", title: "", kind: .int, defaultValue: "64", category: "Direct3D 12", note: "fix: default-buffer-swap: the smallest DEFAULT buffer moved, in MB (at least 8)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "default-buffer-swap-wire", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "1 = VirtualLock (mlock) default-buffer-swap's storage so its pages stay resident; 0 = pageable (as before)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "desc-guard", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: log descriptor writes into shader-visible slots a running batch still uses", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "draw-dedup", title: "Leave out render state the encoder already has", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. A draw no longer sends Metal the pipeline, viewport, scissor, depth-stencil state, blend colour, rasterizer state or buffer bindings the render encoder already holds from the draw before it; a buffer bound again with only a new offset is sent as an offset. Every draw still runs with exactly the state it set (about half of a Horizon Zero Dawn draw's Metal calls were such repeats). 0: every draw sends all of it, as before. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dump-shaders", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "ml1106: madeira.cfg dump-shaders = mdc_x,mdc_y -> Documents/capture/shader_<name>.dxbc, written BEFORE the cache lookup so a cached shader is dumped too.", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "dxbc-register-spaces", title: "Shader model 5.1 resources in register spaces other than 0", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: a DXBC shader (shader model 5.1) that declares a resource in a register space other than 0 is refused, and its pipeline is not created. 1: such shaders are converted, and each resource is bound from the root-signature entry with the same space and register. Horizon Zero Dawn needs it (its constant buffers sit in spaces 6 and 8). Shaders converted with it on are cached apart from the others. Read once per session.", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm", "madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-dump", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "diagnostic: log the bytecode of pipelines with these entry names", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-tess", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "(IRRuntimeNewGeometryTessellationEmulationPipeline): the vertex shader becomes the object function with tessellation on, the hull shader two functions linked into it (hull and tessellator), the domain shader a function linked into the me...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-tess-max-factor", title: "", kind: .int, defaultValue: "3", category: "Direct3D 12", note: "particles through tessellated quads (ls_SetColor, max factor 9): 5,000-7,700 of them, drawn three times a frame, once the fires are going ([probe] log 2026-09-28 14:04) -- up to 162 triangles each through the emulation, and the GPU time ...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "dxil-tess-patch-topology", title: "Experiment: DXIL tessellation with the patch input topology", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Experiment, default off. 1: the stages of a DXIL tessellation pipeline are converted with the converter's patch input topology instead of triangles; such shaders are cached apart.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "encode-batch", title: "One Metal call per encoder, not per draw", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. The commands a replay hands to one Metal encoder (every draw's state and draw, the encoder's fence wait and update) are queued and handed over in one call when the encoder ends, instead of one call into the Metal bridge per draw: the same commands in the same order, with ~1,500 fewer crossings a frame in Horizon Zero Dawn. 0: one call per draw, as before (for telling a regression apart on the device). Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "encoder-labels", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1142: madeira.cfg encoder-labels = 1 names every Metal encoder after the pass that opened it (\"R#<seq> <vs>|<ps>\", \"C#<seq> <kernel>\", \"B#<seq> copy\"), so Instruments' Metal System Trace attributes GPU time per pass. Off by default: on...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_AGS_ROUNDTRIP_ONLY", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ags.cpp"]),
        ConfigOption(key: "env.MADEIRA_APP_IMAGE_UUID", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "set by the app: not a switch", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_CAPS_BY_FAMILY", title: "Report 64-bit atomics and wave operations by GPU", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: both are claimed on every GPU, as before. 1: 64-bit atomics (OPTIONS9, OPTIONS11) only on Apple9 GPUs (A17 Pro, A18, M3 and later) and wave operations (OPTIONS1) only from Apple7 (A14, M1), for an engine that picks shader paths the GPU cannot run.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_CS_DUMP", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "400 files into C:\\madeira-cs on every run cost startup time for a diagnostic that is only wanted while chasing one kernel.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_DXIL_CACHE", title: "", kind: .bool, defaultValue: "", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_DXIL_CACHE_MB", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_ONEPASS", title: "", kind: .bool, defaultValue: "", category: "Direct3D 12", note: "ml1990: one conversion call instead of two. The size-then-fill protocol ran the whole compiler for the size query and again for the fill (the DXIL path had no cache to catch the second). A first buffer of four times the input plus 64 KB ...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_D3D12_RS_DESERIALIZER", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "Read once. The switch exists so a device regression can be separated from this path without a rebuild.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_D3D12_TYPED_UAV_LOAD", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "ml1970: FORMAT_SUPPORT below already reports UAV_TYPED_LOAD for every uncompressed colour format (Metal read-write textures), but this option stays FALSE by default: reporting it can move an engine that already runs onto different render...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_IR_NO_BOUNDS_CHECK", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "madeira-bcd: switches the converter service reads (madeira_ir_unix.mm, madeira_ags.cpp); set in madeira.cfg, as an env.NAME export there, or in the environment. \"msc\" = position invariance, strict NaN/Inf, sampler LOD bias (the MSC compa...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_MSC_DYLIB", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "Host-only: lets the offline round-trip test point at the converter in the extracted package. Compiled out of the device build entirely, so the shipping runtime has exactly one place it will load the converter from.", choices: [], sources: ["madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "env.MADEIRA_PSO_ARCHIVE_INLINE", title: "Pipeline archive: compile once", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "With pso-archive on: 1 (default) compiles a pipeline the saved archive does not have once, into an open archive, and creates it from there. 0: created, then compiled again on one queue to be added (the first version; it kept about a quarter of a session's pipelines).", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "env.MADEIRA_PSO_ARCHIVE_MB", title: "Pipeline archive: size cap (MB)", kind: .int, defaultValue: "1024", category: "Direct3D 12", note: "With pso-archive on: the most a game's pipeline archive folder keeps across builds. Over it, the oldest chunks are deleted at launch down to three quarters; a session adds none once it is reached.", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "env.MADEIRA_PSO_ARCHIVE_PER_BUILD", title: "Pipeline archive: one per build", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "1: the archive folder sits in the build's shader cache directory and goes with it when a new build prunes it (the first version). Off: Madeira/PipelineArchive in LOCALAPPDATA, kept across builds.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_X64_GRAPHICS_ENTRY", title: "Patchable x64 graphics method entries", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1 exposes typed x64 ARM64EC entries for swapchain Present/Present1, ResizeBuffers/ResizeBuffers1 and queue ExecuteCommandLists/GetTimestampFrequency/GetClockCalibration/GetDesc/Signal/Wait. With a DXMT dxgi that has the x64 entries, also selects the factory's patchable MakeWindowAssociation and swapchain-creation entries. The x64 entries use the loader's PE addresses so code patches and nearby allocations agree. Existing native implementations remain behind the entries. Restart the game session.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_graphics_entry.h"]),
        ConfigOption(key: "f6-compute-open", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1116 ml1134: see f6_begin ml1137: counts only madeira-bcd f6-rar", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "f6-rar", title: "Experiment: fence-chain 6 ignores read-to-read barriers", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off; only with fence-chain = 6. 1: a ResourceBarrier whose every transition goes from read states to read states (or is the first half of a split barrier) no longer makes the next GPU pass wait for all earlier ones, and no longer ends an overlapping render pass (which writes its targets to memory and reads them back). Direct3D 12 orders nothing at such a barrier; a game that relied on it anyway would show flicker. Read once per game start; [perf] f6-rar lines count them.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fence-chain", title: "D3D12 fence chain mode", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1114: 2 was clamped to 1 in ml1110-ml1113", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "app/Madeira/FPSOverlay.swift"]),
        ConfigOption(key: "fence-early", title: "Fences advance when the GPU reached their batch", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a job whose command buffers have no query results advances its fence right after the GPU's shared event, and its buffers are retired in order on a second thread; under the CPU clamp the completion bookkeeping took 2-5 ms per job, which a game that polls its fences many times a frame waited for. Jobs with query results, a full ring or upload-guard take the old order. Read once per game start; [perf] fence-early lines show it.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fence-poll-backoff", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "N >= 2 = a thread that polls one unchanged fence N times in a row (each within 50 us) sleeps until it moves, at most fence-poll-backoff-us; 0 = the locked read, as before", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fence-poll-backoff-us", title: "", kind: .int, defaultValue: "200", category: "Direct3D 12", note: "fence-poll-backoff: the longest sleep in microseconds (20..2000), rounded up to whole milliseconds", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fence-strict", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: 1 = Queue::Wait waits for the commit and batches finish in serial order; 2 = also synchronous Signal and Present waits for its frame (slow)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fi-field-check", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: every N presents (1 = 60) read back FSR 3's R32 vector fields before its Setup pass and after each later FidelityFX dispatch of that frame; log texels whose low half is a NaN/Inf half-float ([fi-field])", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fi-nan-clean", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: after each FidelityFX dispatch that binds one of the R32 vector fields FSR 3's Setup pass binds, a helper kernel zeroes the field's texels whose vector half (bits 0..15) is a NaN/Inf half-float (HFW's black squares); 2 = also when b...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fi-setup-zero", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: zero-fill the R32 UAV textures of FSR 3's frame-interpolation Setup pass with a blit just before it (black squares: is Setup's own clear lost?)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "fullscreen-window", title: "Full screen moves the game's window over the whole screen", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: when a Direct3D 12 game switches to full screen, its window is moved to the screen's top-left corner and over the whole screen first, as Windows does; the game then sizes it to the chosen mode. Without it a game that only resizes its window (Red Dead Redemption 2) keeps it where it was, beside the Wine desktop. Read once per session.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-fault-info", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "Batch command buffers are created with encoder execution status (madeira_ctl op 8, winemetal in DXMT), and a failed one logs its faulted encoders by label (op 9). After the first fault every encoder is labelled, a compute encoder runs ON...", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-fault-skip", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gpu-sync", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: every ExecuteCommandLists commits its batch and waits until the GPU has finished it (no CPU/GPU overlap at all; slow)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "gs-null-fragment", title: "Empty fragment function for pipelines without a pixel shader", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. Metal aborts on a mesh pipeline (geometry shader or tessellation emulation) with rasterization on and no fragment function, while D3D allows a pipeline with no pixel shader. On: such a pipeline gets an empty fragment function and writes no render target, as in D3D; depth and stencil work as before. Horizon Zero Dawn's pipeline thread died without it and the game stopped after its first frame. 0: such a pipeline is refused instead (the geometry shader is dropped). Pipelines with a pixel shader are not touched. Read once per session.", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "heap-backing", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1145", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-count", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: log N frames (1 = 3000) of per-pipeline ExecuteIndirect instance / threadgroup totals read back from the GPU; one-frame dips are flagged", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-count-from", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ind-count: the first present logged", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ind-probe", title: "ExecuteIndirect probe (diagnostic)", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. Every 3 s per pipeline, the first argument record of an ExecuteIndirect is read back by a small compute pass and logged as a [probe] line, 1500 lines at most. Each probe ends the open render pass. 0: no probes (Red Dead Redemption 2's list, build 476).", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "indirect-fast", title: "Encode ExecuteIndirect records without per-record setup", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: after the first record of an ExecuteIndirect, the other records (which share all state but their offset) are encoded 64 at a time with only their offset and the indirect draw or dispatch, instead of the whole per-draw setup each. For games that issue thousands of indirect records a frame (Red Dead Redemption 2), where that setup costs more CPU time than the GPU spends. DXIL and DXBC pipelines (DXBC from build 470); pipelines with tessellation or geometry stages, diagnostics and captures keep the per-record path. Read once per session.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "metalfx-upscale", title: "MetalFX upscaling factor", kind: .choice, defaultValue: "", category: "Direct3D 12", note: "Scales the presented picture with Apple's MetalFX spatial scaler (Direct3D 11 and 12). Usually set per game in Game details > Display.", choices: [("", "Off"), ("1.5", "1.5x"), ("2", "2x")], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "app/Madeira/ContentView.swift"]),
        ConfigOption(key: "mip0-full", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: a texture created with MipLevels 0 gets the full mip chain and GetDesc answers its count, as D3D12 does (FSR 3.1 frame generation's inpainting pyramid: Horizon Forbidden West's black squares); 0 = one level, GetDesc answers 0", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "msc-bounds-check", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-fail-memo", title: "Remember refused shaders for the session", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a shader the converter refused is not converted again for the next pipeline that uses it (same bytecode, root signature and options) until the game exits. Horizon Zero Dawn converted each refused shader ~6 times, ~30,000 conversions in its first minutes.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "msc-position-inf-nan", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira-bcd: madeira_ir_unix.mm, build 217", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-position-invariance", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-sample-nan-zero", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira-bcd: madeira_ir_unix.mm, build 217", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-sampler-lod-bias", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-strict-nan", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
        ConfigOption(key: "msc-unbounded-retry", title: "Retry refused shaders with sized unbounded ranges", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a DXIL shader the converter refuses with code 4 (a resource not in the root signature) is converted once more with the root signature's unbounded descriptor ranges given a size (2048 samplers, 1000000 others). Horizon Zero Dawn's ranges start at register 4 and ~4,900 of its shaders were refused. Once that works for a root signature, its later shaders take the sized ranges first.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "occlusion-visible", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "ml1103", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "perf-log", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1108: where does the frame go? GPU busy (union of command-buffer GPU intervals), CPU time blocked in retire, presents -- logged every 5 s from Present. Off with madeira.cfg perf-log = 0.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "present-min-ms", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: Present sleeps so that frames are at least N ms apart (200 = 5 fps), like the main menu's slow first seconds", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-archive", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "compiled pipelines kept in Metal binary archives of our own (1; 0 = Metal's cache only)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-async", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "madeira.cfg pso-async: 1 = a new render pipeline is built on a background thread and its draws are skipped until it is ready (no frame waits for the compiler); 0 = built at its first draw", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-first-use", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: log every pipeline the first time a command list binds it, with the present it was created at", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-lazy", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira-bcd: madeira.cfg pso-lazy (default 1), see mad_pso_realize", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-lazy-libs", title: "Shader libraries only for pipelines in use", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a pipeline built at its first draw (or dispatch) lets its converted Metal libraries go once the game has created it, and reads them back from the shader cache at that first draw. Horizon Zero Dawn creates ~52,000 pipelines in its menu and draws a few thousand; their libraries held hundreds of MB until iOS closed the game. Needs the shader cache (on by default); with pso-warm, a library stays until its warm-up compile is done.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-parallel", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira.cfg pso-parallel (default 1): a batch's new pipelines built in parallel", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-placeholder", title: "Placeholder for pipelines whose shaders did not convert", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a graphics pipeline whose vertex or pixel shader did not convert is returned to the game as a placeholder whose draws are skipped, instead of a failure. Horizon Zero Dawn stopped with an \"Error\" box when its settings menu got such a failure.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "pso-share-libs", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "madeira.cfg pso-share-libs (default 1): identical converted libraries share one MTLLibrary. 0 keeps one per pipeline (the table is never trimmed, so this is the switch to compare memory with).", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "query-timestamps", title: "Timestamp queries from the CPU clock", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off: every timestamp resolves to zero. 1: a resolved timestamp is the process's monotonic clock in ns when the resolve is recorded (plus its place in the range), and GetClockCalibration's GPU value is the same clock, for a game that spins on zero timestamps. Nothing is measured on the GPU. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "queue-trace", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: log the first N ExecuteCommandLists / Signal / Wait calls (1 = 400) with thread, queue type and fence state", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "quiet-log", title: "Cheaper Direct3D 12 logging (no census frames)", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "1: the Direct3D 12 runtime's log lines skip OutputDebugString (an exception and a server request each, ~0.5 ms a line on the device) and reach the log through Wine's own debug output and stderr only; the census frames between presents 1500 and 3000 and the list 12000-12400 draw dumps are off (each froze the game for 1-2 s); the per-shader \"converted at runtime\" line is kept for the first 64 shaders and then every 1000th. A manual frame capture still works. Default off: the logging as before.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "readback-far", title: "Experiment: empty culling readback", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a readback of a depth pyramid (an R32_FLOAT mip of 1 or more of a texture with 4+ mips, up to 64x64) is not copied; the CPU fills it with 4096, so a game that culls on the CPU against it culls nothing (everything is drawn: slower). A test, not a fix. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "readback-swap", title: "D3D12 readback buffers on file-backed memory", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on: like upload buffers (upload-swap), READBACK buffers of 8 MB or more live on file-backed storage, off the memory footprint. 0: READBACK buffers get Metal's own memory (Horizon Zero Dawn: two 32 MB buffers), so what the GPU writes into them reaches the CPU without the file tier between; upload buffers stay where upload-swap puts them. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "replay-split", title: "Log where Direct3D 12 submission time goes", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off, logging only. 1: every 5 seconds a [perf] replay split line divides the time ExecuteCommandLists takes per frame into waiting for the queue, preparation, opening a command buffer, each kind of command (draws, dispatches, copies, clears, barriers, render targets, queries, state) and the end of each list. For finding why a game's frame is slow when the GPU is not busy.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "ring-share", title: "Share argument buffers between command lists", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a command list gives the argument-buffer chunks its replay wrote back as soon as the GPU is done with them, instead of keeping them until it is recorded again; all lists then share one pool. Red Dead Redemption 2 kept 1.5 GB of them (half of its Metal memory) with the switch off.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-carry", title: "Experiment: render passes go on into the next command list", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: when a command list ends inside a render pass and the next list of the same submission draws to the same targets first, with only state between the two draws, the pass stays open: its targets are not written to memory and read back. Horizon Zero Dawn records its depth and G-buffer passes in ~20 lists (0.3-0.6 GB a frame of such writes and reads), GTA V Enhanced its G-buffer in ~12. Opt-in: the second list's draws no longer wait for the whole first pass, an ordering Direct3D 12 does not promise but a game might rely on. Read once per game start; [perf] gpu-traffic lines show what it saves.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-discard", title: "Experiment: no load after, no store before DiscardResource", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: after a game discards a whole render target or depth buffer (DiscardResource), the next render pass that draws to it does not read its old contents from memory, and a pass whose target is discarded (or cleared whole) next, before any other use in the same submission, does not write it back -- as tile-based GPUs do on Windows. Opt-in: a game that still reads what it discarded (desktop GPUs ignore discards) would show garbage there. Read once per game start; [perf] gpu-traffic lines show the bytes.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "rp-lean", title: "Render passes fill only the targets they use", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "Default on. A Metal render pass is described with only the colour targets it uses; the bridge filled all eight slots for every pass (~240 Objective-C calls and 8 allocations a pass, a few hundred passes a frame). Metal ignores a slot without a texture, so the pass is the same. Also used by Direct3D 9/10/11 games through DXMT. 0: all eight slots, as before. Read once per game start.", choices: [], sources: ["dxmt/src/winemetal/unix/winemetal_unix.c"]),
        ConfigOption(key: "sampler-census", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: log every distinct sampler filter value once with its Metal mapping", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "shader-cache", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "shader-cache-native", title: "D3D12 shader cache files read natively", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "On by default. The Direct3D 12 runtime's shader cache (AppData\\Local\\Madeira\\ShaderCache) is read and written by Madeira itself instead of through Wine's file calls, which asked Wine's server three times per entry (~3.5 ms each in Horizon Zero Dawn's menu, ~1,000 entries a second, with the server on a performance core). The same files either way. 0: Wine's file calls, as before. Read when the game creates its first pipeline.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check", title: "Diagnostic: check meshes skinned on the GPU", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "Default 0 (off). N: windows of N frames (1 = 8) log every draw that reads a vertex buffer a compute shader wrote, the dispatches that wrote it with every binding, a summary of up to 32 KB of each such stream copied just before the draw, and the shaders' bytecode. For characters drawn with missing faces or spikes (Horizon Zero Dawn); costs time in those frames.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-capture", title: "Diagnostic: skin-check copies the streams", kind: .bool, defaultValue: "1", category: "Direct3D 12", note: "On by default with skin-check. 0: log only, with no GPU copies, which add a copy between the skinning dispatches and the draw (to compare what the frames look like).", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-every", title: "Diagnostic: presents between skin-check windows", kind: .int, defaultValue: "300", category: "Direct3D 12", note: "With skin-check on: a window starts this many presents after the previous one began (at least 30); the first starts 60 presents after the first such draw.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-check-trace", title: "Diagnostic: skin-check traces whole frames", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1, with skin-check on: the first frame of the first two windows logs every draw in one line (shaders, counts, streams, input layout); a pipeline with integer vertex inputs (a mesh skinned in its vertex shader) also gets its vertex-stage bindings, copies of its CPU-written inputs and first vertices, and its vertex shader's bytecode (32 such draws).", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skin-dump", title: "Diagnostic: skin-check dumps the skinning data", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1, with skin-check on: in the first window's first two frames the compute shaders that skin a mesh have their inputs and the stream they wrote copied whole (up to 256 KB each) and logged as base64 (4 MB at most), so the skinning can be recomputed on a PC. Uses a 24 MB capture buffer.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skip-ps", title: "", kind: .text, defaultValue: "", category: "Direct3D 12", note: "diagnostic: drop the draws of these shader entries (comma list, exact names)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "skip-ps-cycle", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: rotate skip-ps one name at a time, N seconds each (0 = skip all at once)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "sm5-flat-views", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "static-cbv", title: "Constant buffers as the draw was recorded", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "Default off: the GPU reads every descriptor of a table when it runs. 1: a descriptor table's single constant-buffer ranges are read when each draw or dispatch is recorded, as NVIDIA's driver and vkd3d-proton do; a game that rewrites one after recording the draw no longer makes that draw use another object's constants. Ranges marked VOLATILE stay as before. 2: VOLATILE ones too (vkd3d-proton's force_static_cbv). 3: only count the rewrites ([static-cbv] lines). Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "tv-hash", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "fix: typed-buffer views are found through a hash table once a resource has 32 of them, instead of a scan of all of its views under the device-wide view lock; 0 = the scan as before", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-uav-atomic", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix attempt: R32 UAV texture-buffer views (RWBuffer<uint>, UAV counters) get ShaderAtomic usage", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-view-align", title: "Typed buffer view alignment", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "Default 0 (64 bytes, as before). 16 or 256: a typed buffer view's texture starts at that boundary, never below Metal's minimum for its format (logged once per format); 16 is what Apple's converter documents, so a float4 view has no padding elements. 4: every view's texture starts exactly at its first element, for the element sizes a GPU probe at the first view shows read right (logged); the others start at 16. A view Metal refuses there is made at 16, then 64. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-view-rgb32", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "fix: typed SRVs of UPLOAD memory in an R32G32B32 format (no Metal texture-buffer format) read a copy with 16-byte elements through an RGBA32 texture buffer", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "typed-view-shadow", title: "Aligned copies of offset typed views", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: a typed shader-resource view of UPLOAD memory whose first element is not on a 16-byte boundary reads a 16-byte-aligned copy of its bytes, made when the view is made and refreshed at every ExecuteCommandLists (the GPU rounds a texture buffer's start down to 16 bytes and the shader converter ignores the element offset). view-census counts them. Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-guard", title: "", kind: .int, defaultValue: "0", category: "Direct3D 12", note: "diagnostic: 1 = log UPLOAD-heap data the game rewrites while the GPU still uses it; 2 = also compare with what the GPU read", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-guard-bytes", title: "", kind: .int, defaultValue: "256", category: "Direct3D 12", note: "bytes upload-guard hashes per range (16..4096)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "upload-swap", title: "D3D12 upload buffers on file-backed memory", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "ml1154: madeira.cfg upload-swap (default 1)", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "use-dedup", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "A draw's declarations count only once its chain has been encoded: a draw that returns early leaves them uncommitted, and the next begin drops them.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "view-census", title: "Diagnostic: report buffer views that fall back", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: typed buffer views that cannot become a Metal texture buffer (the shader then sees no data), views cut short at the end of their resource, and views or constant buffer views past their resource are counted and named in the log, with Metal's minimum alignment for each pixel format typed views use. Changes nothing else.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "vis-trace", title: "Diagnostic: per-frame draws and culling readback", kind: .bool, defaultValue: "0", category: "Direct3D 12", note: "Default off. 1: one log line per present (the HUD's frame number): draws, depth-only and 3+-target draws, indices, dispatches, depth-pyramid readback copies, new offset typed views, and Queue::Wait calls (how many passed before the awaited batch was committed); and every value of the 22x10, 11x5 and 5x2 mips of the pyramid a game culls with, as the GPU wrote them. The GPU also copies each of those mips into Madeira's own memory, and a mip whose readback memory holds something else is flagged (an earlier frame's values: STALE). Read once per game start.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "vsps-fill", title: "", kind: .int, defaultValue: "1", category: "Direct3D 12", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c", "madeira-d3d12/src/unix/madeira_ir_unix.mm"]),
