        ConfigOption(key: "env.MADEIRA_FAULT_ESR_DIR", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "The data abort's ESR says whether the access wrote (WnR, bit 6). The encoding guess below calls the LSE atomics (LDADD, SWP, CAS...: an x86 lock xadd / xchg) reads, because they have bit 22 set, so a write was reported to the guest as a ...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FAULT_GUARD_GUEST_RIP", title: "Fault guards tell FEX's invalid instructions apart", kind: .bool, defaultValue: "0", category: "Exceptions & threads", note: "Default off. 1: the fault-storm guards also key an invalid-instruction delivery on the guest instruction FEX saved, so a program that steps over a long run of them in its own handler is not ended while it advances, and the 50-fault page breaker counts memory faults only. Logged as [redeliv] guest_rip. Read once per session.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FAULT_GUARD_RATE", title: "Fault-storm guards end only a real storm", kind: .bool, defaultValue: "0", category: "Exceptions & threads", note: "Default off. 1: a run of 2000 faults at one instruction ends the game only when it is dense (inside half a second) or presenting makes no progress, and the 5-repeat guard counts per thread within 5 ms; for a Unity title that throws managed exceptions through null-check traps while it keeps drawing. Read once per session.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FAULT_LOOP_GUEST_PROGRESS", title: "A run of breakpoints at different addresses is not a stuck thread", kind: .bool, defaultValue: "0", category: "Exceptions & threads", note: "Default off. 1: the loop breaker (50 faults at one place end the thread) no longer counts int3 traps at different guest addresses as one stuck fault, though the emulator raises all of them from one host instruction. Logged as [fault-progress]. Read once per session.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
