        ConfigOption(key: "env.MADEIRA_ODD_VTABLE_REPAIR", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "mov rax, [rcx] ; loads RAX = klass | 1 mov rdx, [rax + 0x210] ; 1-byte misaligned read -> (slot1 >> 8) | (slot2 << 56) call [rax + 0x208] ; 1-byte misaligned read -> (slot0 >> 8) | (slot1 << 56) while bit 0 is set. The shifted read place...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_NOEXEC_GIVEUP", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "code again (the ml1351 [pool-poison] class). When the faulting code is the process's own ntdll copy, the exception dispatcher sits on the same dead pages, so delivering the fault faults again at the dispatcher, forever: device log 81, tw...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_PROCESS_APC_QUEUE", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "duplicated that handle, so the action returned 5 and the install ended with 1603. * Instead queue it on the process's first live thread; that thread runs system APCs at its next interruptible server wait (check_wait returns STATUS_KERNEL...", choices: [], sources: ["wine/server/thread.c"]),
        ConfigOption(key: "env.MADEIRA_RECOVERY_LOG_SAMPLE", title: "Sample routine instruction recovery logs", kind: .bool, defaultValue: "0", category: "Exceptions & threads", note: "Default off. 1: of FEX's records about each recovered invalid instruction (C000001D) only the first 16 and every 1024th are kept, and of the shared-trap ILL reports the first 8 and every 1024th; only the log changes. For a game that recovers thousands a second. Read before guest threads start.", choices: [], sources: ["build/ntdll-unix/loader_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REDELIV_CHILD_ONLY", title: "A fault storm in a helper program ends only that program", kind: .bool, defaultValue: "1", category: "Exceptions & threads", note: "Default on: when the fault-storm guard gives up on a thread of a program the session started (a launcher's helper), that program ends and the app keeps running; the session's first program keeps the old ending. 0: the whole app ends for every storm, as before.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REDELIV_VPROTECT", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "A protection change between two deliveries (FEX's self-modifying-code cycle: unprotect, recompile, protect again) is real progress. Tag redeliv_guest_rip with the protection sequence number so the consecutive counter below starts a new r...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRCWATCH", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "competing for it means whichever runs first silently wins and the other is never armed at all — a probe that reports nothing while looking healthy. There are now two subjects: * \"render\" — win32u's dibdrv_PutImage, Chromium's SOURCE bitm...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRCWATCH_ROWS", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "1. TARGETING. Arming the whole 1.2MB bitmap spreads a 400-attribution budget across ~76 pages, so the clear (which touches EVERY page first) dominates and the content painters — the writers that would name a displaced band — stay invisib...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRW_HANG_DIAG_S", title: "Diagnostic: 32-bit SRW-lock hangs", kind: .int, defaultValue: "30", category: "Exceptions & threads", note: "ml2250: a 32-bit thread that has waited this many seconds without a timeout for an SRW lock held by shared owners has every 32-bit thread of its process logged once ([srw-hang]: x86 registers, EBP chain, module-resolved stack words), so the holders are named. Logs 116-119: Steam's 32-bit web helper stopped at start that way. 0: off.", choices: [], sources: []),
        ConfigOption(key: "env.MADEIRA_SRW_HANG_KILL_S", title: "End a process stuck on an SRW lock", kind: .int, defaultValue: "", category: "Exceptions & threads", note: "ml2250: unset (default): never. N: once a 32-bit thread has waited N seconds for an SRW lock as above, the wineserver ends its process, as TerminateProcess from another process would, so a parent that restarts its helper gets a new one (Steam restarts its web helper). At most 3 per app run. The Steam Big Picture list sets 40.", choices: [], sources: []),
        ConfigOption(key: "env.MADEIRA_TASK_EXC", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "Opt-out only: this strictly removes a dependency on a port we do not own, so it defaults ON. MADEIRA_TASK_EXC=0 restores the pre-ml522 behaviour for a same-build A/B against the ~54s stall.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THREAD_QOS", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "end = 0;", choices: [], sources: ["build/ntdll-unix/thread_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THREAD_REAP_CHECKED", title: "Check the previous exited thread before freeing it", kind: .bool, defaultValue: "1", category: "Exceptions & threads", note: "ml2290: on (default): a thread that exits frees the previous exited thread's stacks only after finding that thread, by its process, thread id and pthread, in the live TEB list (the hand-off env.MADEIRA_EA_CEF = 1 already used). 32-bit processes started one after another can get the same window and TEB addresses; the unchecked hand-off then made a new thread free its own kernel stack at exit and hang there holding the memory lock (testers' log, 2026-10-31: a launcher installer's second VC++ redistributable, the installer waiting on that thread forever). 0: the upstream hand-off, unless MADEIRA_EA_CEF = 1.", choices: [], sources: ["build/ntdll-unix/thread_ios.c"]),
