        ConfigOption(key: "env.MADEIRA_WOW_REAP_DEAD", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "[wow-reap]: a thread of an EXITED process that is held suspended (the [zombie] rule's or ios_thread_registry_end_dead_range's fallback when thread_terminate is refused) never runs again, so it cannot touch the window: it does not hold it...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WX", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "ml695: OFF BY DEFAULT. This optimization has known stale-translation and address-reuse hazards and has already produced deterministic crashes in two builds; silent corruption on a fresh install would be worse than a clean crash, and a ki...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_X18_SIGNED_LOAD", title: "", kind: .text, defaultValue: "", category: "Exceptions & threads", note: "ios_mach_exception_thread). It decoded the zero-extending unsigned-offset loads (LDR X, LDR W, LDRB, LDRH) but not the sign-extending ones, so the access was declined as \"UNRECOGNIZED\" and the thread died: `ldrsw x28, [x18, #0x180c]` (0x...", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GL_QUERY_BUFFER_OFFSETS", title: "32-bit GL query results as buffer offsets", kind: .bool, defaultValue: "1", category: "Graphics", note: "On (default): a 32-bit program's glGetQueryObject*v result pointer is an offset into the bound GL_QUERY_BUFFER (wined3d reads occlusion results that way; converting it as a pointer left the game spinning at 1 fps, ml1340). 0: the old pointer conversion.", choices: [], sources: ["wine/dlls/opengl32/unix_wgl.c"]),
        ConfigOption(key: "gl-vulkan", title: "Vulkan driver for OpenGL (Zink)", kind: .choice, defaultValue: "", category: "Graphics", note: "The Vulkan driver Zink runs desktop OpenGL (and d3d9 = wined3d) on: MoltenVK (default) or KosmicKrisp (gl/libvulkan_kosmickrisp.dylib); any other value is a .dylib name in the gl folder or an absolute path. env.MADEIRA_GL_VULKAN is the fallback. Read when a program first creates an OpenGL context; the log says \"ml1344 zink Vulkan library: ...\".", choices: [("", "MoltenVK (default)"), ("moltenvk", "MoltenVK"), ("kosmickrisp", "KosmicKrisp")], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DIAG", title: "", kind: .text, defaultValue: "", category: "Media", note: "MADEIRA_DIAG=1 lifts the cap; read once. Local to this file so the media unix side links against nothing but upstream's libntdll_unix.a.", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WG_PARSER", title: "", kind: .text, defaultValue: "", category: "Media", note: "", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WG_VIDEO", title: "Media: MP4 video (32-bit programs)", kind: .text, defaultValue: "", category: "Media", note: "0 limits the media parser to MP3/WAV; by default MP4 with H.264/HEVC video decodes through VideoToolbox.", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WG_VIDEO_FORMAT", title: "", kind: .text, defaultValue: "", category: "Media", note: "", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WMA_DUMP", title: "", kind: .text, defaultValue: "", category: "Media", note: "", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WMA_SEARCH", title: "", kind: .text, defaultValue: "", category: "Media", note: "ml1120: MADEIRA_WMA_SEARCH=0 pins the decoder to the rate and flags this file worked out from the media type alone, which is what shipped before the ladder. A packet it cannot decode is then concealed with silence of that packet's length...", choices: [], sources: ["build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "arena-mb", title: "", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "ml1095: madeira.cfg arena-mb = N", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "avail-phys", title: "Report the memory left before the app's limit as available", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: Windows programs' available physical memory (GlobalMemoryStatusEx) is what remains before Madeira's memory limit instead of the phone's free memory, so Chromium (Social Club, Steam) frees caches below 1000 MB and 400 MB left, and a game can see memory running out. Set it in the game's own file; read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "avail-phys-cef-mb", title: "Available memory Chromium sees (MB)", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "0 (default): off. N: Social Club's SocialClubHelper.exe and Steam's steamwebhelper.exe see at most N MB of available physical memory, nobody else (the game and the launcher keep the real figure). Below 400 (e.g. 300) Chromium reports critical memory pressure every 5 s and purges caches and garbage; 400-999 (e.g. 900), moderate every 10 s. Independent of avail-phys. Set it in the game's own file; read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "donor-only", title: "Donor pool without a swap file", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "ml2200: on (the default), donor-pool-mb set and swap-mb unset start the swap tier with the donor pool as its only stage: no swap file is made, and memory the pool cannot cover stays normal app memory (iOS compresses it inside the app's limit). 0: without swap-mb the donor pool is not started, as before. Read at launch.", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "donor-pool-guard", title: "Donor pool: memory-pressure guard", kind: .choice, defaultValue: "0", category: "Memory & JIT pool", note: "ml2021: what iOS's memory-pressure notification does to the pool. Unset: nothing, the pool is spent like MeloNX's (on an 8 GB phone the critical notification refused 502 takes and left 2.6 GB of the pool unused while the title's own memory, compressed, filled the app's limit; donated pages are the extension's to compress, not the app's). 1: a critical notification stops takes. 2: warning and critical (the old behaviour).", choices: [("", "Off (spend the pool)"), ("1", "Stop at critical pressure"), ("2", "Stop at warning")], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "donor-pool-kind", title: "Donor pool memory kind", kind: .choice, defaultValue: "", category: "Memory & JIT pool", note: "ml1152: how the extension creates each donated region. ledger (the default): a named memory entry tagged to the extension's ledger. purgeable: a purgeable allocation in the extension named by a memory entry (the way MeloNX donates RAM). Everything else in the tier is the same, so the two can be compared.", choices: [("", "Ledger-tagged entry (default)"), ("purgeable", "Purgeable allocation")], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "donor-pool-mb", title: "Donor pool size", kind: .choice, defaultValue: "0", category: "Memory & JIT pool", note: "ml1150: RAM for the swap tier that is not counted against Madeira's limit, donated by the MadeiraMemoryHost extension (512 MB regions, created untouched, handed over, then the extension exits). With swap-mb it is the swap tier's first stage, taken before the swap file; without swap-mb it is the only stage (ml2200 donor-only, madeira.cfg donor-only = 0 turns that off) and what it cannot cover stays normal app memory. Taken while free RAM stays above MADEIRA_DONOR_POOL_MARGIN_MB and iOS reports no memory pressure. Off by default; read at launch.", choices: [("", "Off"), ("2048", "2 GB"), ("4096", "4 GB"), ("6144", "6 GB")], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_ALIAS_PER_PROCESS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Default on. 0 restores the old pushes: every image goes to the emulator that registered last, and a registration drains every process's images.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_ALIAS_RELEASE", title: "Drop a released arena's code copies", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: anonymous memory the game made executable (copied into the JIT pool) follows the game's MEM_RELEASE and MEM_DECOMMIT: a released view drops its copies' records, a decommit zeroes each copy in its pool slot. For a game that releases a memory arena and reserves it again at the same base. Logged as [alias-release]. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_APP_UCRT", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_ARENA_GUARD", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "On by default. MADEIRA_ARENA_GUARD=0 lets a fixed or hinted guest reservation take FEX arena space again.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_AUX_IAT_HEAL", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0: EC import stubs keep the exec-fault redirect", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CAGE_RELEASE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1: when the guest band is exhausted, hand the unclaimed 8 GB V8 cage holdback to it. Set by the app for a Madeira Dock session; off otherwise.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_COW_OLD_PROT_RW", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1310: Windows reports a copy-on-write image page as read-write once it has been written (its private copy exists). Wine maps image pages writable from the start and cannot tell, so it always said WRITECOPY; V8 CHECKs that the flags pag...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CREATE_VIEW_REFUSE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Create a view. virtual_mutex must be held by caller. create-view refuse: a title died here 89 s in, while FEX started a thread and asked for 16 MB: \"Assertion failed: (view->protect & VPROT_SYSTEM), function create_view\", exit 0x80000101...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DEP_PER_PROCESS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "(SetProcessDEPPolicy, permanent) therefore switched DEP back on for a running 32-bit game that had turned it off, and virtual_set_force_exec's sweep re-protected every view of every pseudo-process from the browser's thread: every executa...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DETACHED", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "≤30min at 2s — covers the 20-min cap", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DNSAPI_UNIXLIB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "dnsapi's unix side is bound unless MADEIRA_DNSAPI_UNIXLIB=0, which keeps the stub table (every dnsapi unix call STATUS_NOT_SUPPORTED) as before.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DONOR_BROWSERS", title: "Browsers take donor RAM", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Off by default: memory of the Chromium browsers next to a game (Social Club's SocialClubHelper.exe, Steam's steamwebhelper.exe) is backed by the swap file, never by the donor pool. The pool is handed out by reserved size whether the pages are used or not, and Social Club's 4 GB allocator reservation used to take all of it before the game asked. 1: browsers take donor RAM like any program. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DONOR_CHURN", title: "Short-lived memory takes donor RAM", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "On by default: memory a game frees and allocates again soon takes donor RAM while the pool has room, instead of counting against the app's memory limit. 0: it stays in the app's own memory as before. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DONOR_POOL_MARGIN_MB", title: "Donor pool free-RAM margin (MB)", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1150: the donor pool takes no more memory while the host's free RAM is below this many MB. Off (0) since ml2021: iOS keeps free RAM low on purpose, so 1024 and then 256 refused most takes on device; the memory-pressure notification alone guards. Set 256 to restore the old floor.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DONOR_WHOLE_MAX_MB", title: "Largest reservation given donor RAM (MB)", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "0 (default): no limit. N: a reservation larger than N MB is backed by the swap file only, never by the donor pool (a test; a game's own big heap is usually hot and runs faster in donor RAM). Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DONOR_WINDOWS", title: "Donor pool: permanent region windows", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "ml2021: 1 maps every donated region into the address space when it is registered, as the first port did. Off (the default) maps only the range being freed, for its zeroing: the permanent windows were placed before Wine held the 32-bit guest-window slot and took it, so 32-bit programs failed at guest-window-reserve.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EA_CEF", title: "A store launcher's Chromium in one process", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off; set with env.MADEIRA_SC_PA_POOLS = 2 for the EA app's launcher. EADesktop.exe runs --single-process with V8 --jitless (MADEIRA_JITLESS = 0 keeps V8's JIT), its --type= children are refused, and its four PartitionAlloc pools get the four 16 GB slots of the address band instead of overlapping. No effect on any other program.", choices: [], sources: ["build/ntdll-unix/process_ios.c", "build/ntdll-unix/thread_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EA_CEF_CMDLINE", title: "Rewrite EADesktop.exe's command line", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "Default on. 0: while env.MADEIRA_EA_CEF is on, EADesktop.exe's command line is not rewritten; its --type= children are still refused. For testing a switch the launcher may not know.", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EA_CEF_FLAGS", title: "Extra EADesktop.exe switches", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Appended verbatim to EADesktop.exe's command line while env.MADEIRA_EA_CEF is on (e.g. --disable-gpu).", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EXE_WINDOW_HANDOFF", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0 restores the old fixed-base handoff: claims are matched without rounding the image size to host pages, and a new main image never waits for the previous owner of the executable window to exit.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EXE_WINDOW_SMALL_FIXED", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0 keeps the executable window from a fixed-base (relocations stripped) image smaller than 64 MB, as before; such a program then fails to start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EXE_WINDOW_WAIT_MS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "how long a new main image with stripped relocations waits for the previous owner of the executable window to exit, in milliseconds; 0 does not wait", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_EXECREQ_LEAVE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Default off. 1 makes NtProtectVirtualMemory's [exec-req] path clear InSyscallCallback again, so the emulator hears about the memory changes that follow an executable protect on the same thread (GTA V Enhanced, the NoExec crash).", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FEX_ARENA", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Wine reserves a band; the emulator still runs its own selector and picks a different one. Holding 8GB therefore pushes it into whatever is left, and when that band is exhausted its 16MB requests fail, a thread-creation path dereferences ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FEX_ARENA_GROW", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1: a full FEX arena adds a FEX_ONLY band below it (default off: on the Social Club layout a band lies in address space the browser helper's allocators were granted, and their writes corrupted it); default: the request fails as before", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FEX_BAND_KEEP_MB", title: "Keep the lowest MB of the emulator's address range for the emulator", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "Default 0 (off). N MB: reservations of 32 MB to 1 GB that are placed above the game's own range because that range is tight may not take the lowest N MB of the emulator's 16 GB range; what no longer fits goes below it. For a game that reserves many 511 MB ranges and then ends with \"FEXAlloc could not allocate\"; 6144 keeps 6 GB. Only with the 16 GB range at 0x7c00000000. Logged as [fex-keep]. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FEX_HEADROOM_LOG", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0: no [fex-headroom] lines", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FIXED_BASE_GUARD", title: "Keep 0x140000000 for a fixed-base game", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: a resource-only image view (a version or resource query, e.g. the Rockstar Games Launcher reading Social-Club-Setup.exe) never takes the reserved executable window at 0x140000000; it is mapped elsewhere. The window then stays free for a game exe without relocations that can only run there (Red Dead Redemption 2). It moves other programs' images too (GTA V Enhanced's, for one), so set it only in such a game's own file; read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FREE_DELAY_MS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "How long a released 1-16 MB guest allocation stays mapped before it is really freed (default 0: freed at once; 2000 ms is the tested hold).", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FREE_DELAY_REUSE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MADEIRA_FREE_DELAY_REUSE=0: a reservation over held releases fails until the delay runs out, as before; default 1: those held ranges are freed at once", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GUEST_IMAGE_WRITE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "memory is decided by its own rule (ios_guest_anon_rwx_is_host_data, below): a managed runtime's code buffers keep the pool alias and the store emulator, and those views are not SEC_IMAGE. The test is the view, not the address range. * vi...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GUEST_RWX_DATA", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "On by default: a guest's anonymous RWX data heap (Mono's Boehm GC) is plain read/write memory. 0 maps it through the JIT pool again, with every store emulated, as before.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_IAT_SYNC_KEEP", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1199: 0 = the iat-sync translates unchanged file words too (old rule)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_IMAGE_RELOAD", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MADEIRA_IMAGE_RELOAD (default 1): 1 the same image reloaded at the same base by the same process gets its copy rebuilt in place (same pool address, fresh bytes, relocations and x18 patches redone); any other reuse of an unmapped copy get...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_JIT_ATTACH_CHECK", title: "", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "0 treats JIT as ready whenever CS_DEBUGGED is set, as before, without asking whether a debugger is attached.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "env.MADEIRA_JIT_IMAGE_RETIRE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "new module runs the old module's translated code. Tombstone every pool mapping that overlaps the unmapped range before the VA can be reused, so the next image mapped there gets a fresh copy. The pool bytes themselves stay in the process ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_JIT_TRAP_FALLBACK", title: "", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "With no debugger attached, a JIT request fails the launch with a message; 0 lets it crash the app as before. CS_DEBUGGED stays set after a debugger detaches (JIT enabled by a tool that attaches and leaves, or without Madeira's script), a...", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "env.MADEIRA_JUMBO_ALIGNED", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0: a hinted reservation at a 4 GB boundary (V8's trusted range) takes a kernel pick as before, and furniture may fill the 4 GB-aligned gigabyte above a guest window (default 1: 4 GB-aligned bases are tried first and that gigabyte is left...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_JUMBO_HALF", title: "Give a too-large probe reservation half its size", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: a reserve-only request of 4 GB or more (a power of two) that finds no hole gets half its size at a half-aligned free slot below the emulator's arena, for a game that finds each aligned arena with a double-size probe and keeps only half. A game that uses the whole reservation would fault, so set it per game. Logged as [jumbo-half].", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_KUSD_AVX", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1310: with MADEIRA_FEX_AVX=1 FEX runs AVX/AVX2 and its CPUID says so, but Wine fills the XSAVE configuration only on x86 hosts, so GetEnabledXStateFeatures still said \"no AVX\" and runtimes that ask it (.NET's JIT) kept AVX off. Describ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LAA", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "WHAT STAYS LOW regardless (unchanged by this policy, and deliberately so): the first TEB block and the PEB32/TEB32 derived from it (virtual_alloc_teb and the first-block allocation both hardcode limit_2g - 1), the KUSER_SHARED_DATA emula...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LAA_HIGH_IMAGES", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LAA_LOWFIRST", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LAZY_PLACEHOLDERS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MADEIRA_LAZY_PLACEHOLDERS=0 reserves 64 MB to 1 GB placeholders whole again (ml1310)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LOW_ALLOC", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "a low pointer usable by other APIs. Handing a low address to the guest is therefore not viable without translating every API boundary that can receive a buffer pointer, which is a far larger surface than this experiment. * The machinery ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_MAP_RETRY_ANY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "iOS: mach_vm_map can return KERN_INVALID_ADDRESS (→ ENOMEM) at certain addresses due to ASLR/system mappings. Keep scanning instead of aborting. ml1310: ANY refusal means \"not here, try the next spot\" -- also the errno of an mmap over a ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_GL", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Real opengl32 unix side (OpenGL ES / desktop GL through the winios WGL driver). MADEIRA_NO_GL=1 keeps the old GL-absent stub table. The wow64 table's thunks convert every embedded guest pointer with ios_wow_host_ptr() (patches/wine-openg...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c", "build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_HEAL_ESCALATE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: ".data GLOBAL, not an IAT — the IAT-restricted pass finds nothing and the same VA keeps costing one Mach exception per Metal call (118K+ observed; handler saturation = the desktop \"freezes\"). When the IAT pass strikes out, scan each copy'...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_IMAGE_LOW_ALIAS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ios_lowalloc_translate, whole-span bounds-checked) instead. Registration refuses on collision with an image window, another alias, the ml966 arena or the bottom 16 MB, so it can never shadow a real name. * Scope: only images whose PREFER...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_IMAGE_RETIRE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "drops virtual_mutex before returning, so the interval is genuinely free for a moment and another thread may legitimately take it. That is reported as a named loss, never overwritten. * MADEIRA_NO_IMAGE_RETIRE=1 disables the handoff entir...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_LOW_ALIAS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_PLAIN_EXEC", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1: never ask mprotect for PROT_EXEC; every executable request takes the JIT-pool path, as on a TXM device. For iOS 18 and iOS 26 devices without TXM, where it would succeed in place. Default off: as before.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_QUERY_CLIP", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "min_address)) report MEM_RESERVE up to the floor; - otherwise ask the kernel where the next host mapping is. Host ranges inside a Wine reserved area stay free (map_fixed_area may overwrite them); any other host mapping ends the free regi...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NO_SUBFLOOR_XQUERY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml2240: a window above 4GB (between it and the task's floor) is marked with bit 63, which no PE base carries, so FEX files it as a window, not as a JIT alias (IosJitAlias.cpp).", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_NTDLL_DATA_SYNC_RANGE", title: "ntdll data patches copy only the bytes asked for", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: when a 64-bit game changes the protection of a few bytes of ntdll's writable data, only those bytes are copied to the copy ntdll runs from, not the whole page (which also overwrote live callbacks next to the slot). Logged as [ntdll-data-sync]. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_PIN_GRAPHICS_DLLS", title: "Keep graphics DLLs loaded", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. On a D3D12 device/probe call, pins already loaded D3D12, DXGI and Wine Metal DLLs until normal process shutdown, preventing repeated unload/reload copies. Keeps DLL data live; does not recycle executable ranges or change GPU capabilities. Restart the session after changing it.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_PLACE_PROOF", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0 walks the whole map on every failed large mapping; by default a failed walk is trusted for 2 s until a release.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_BIG_SLOT_BELOW", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1 puts the existing image slot below the native hole; 0/default keeps it above.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_BIG_SLOT_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "N MB adjacent to a split-pool hole for one image of 64 MB or more (Social Club's libcef.dll); off by default.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_CODE_EXIT_RECLAIM", title: "Return an exited program's code buffers", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "On by default. When a program of the session exits (a launcher restarting itself, RockstarService.exe, a setup step), the emulator's code buffers it held go back to the JIT pool: reusable 3 seconds later, once no thread runs in them. Before, they stayed in use until Madeira closed, and a game started after many such exits got 16 MB code buffers and ran slowly. 0 keeps them in use, as before.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_HEAD_RESERVE_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "48 to 256 MB of image headroom in the FEX pool-tail budget; 48/default keeps the existing policy. Region C is unchanged.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_LOW_IMAGES", title: "Small images in spare code-buffer space", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. If the normal JIT image allocation fails, copies up to 16 MB may use unallocated region C, preserving 4 MB for code buffers. Requires pool-low; 64-bit processes only. Does not shrink live buffers or the pool-low-margin.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_QUARANTINE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "OUT NON-EXEC off=0xa848000...). The next process started in that session (the windowed taskbar's in-session launcher: services.exe, then steam.exe) got its ntdll copy there and faulted NOEXEC at LdrInitializeThunk's first instruction, fo...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_RECYCLE_IMAGES", title: "Images in retired code-buffer space", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. If other image allocations fail, retired region-C code buffers up to 64 MB may enter the image freelist after a 3-second grace, executable-page and thread-PC checks. Requires pool-low; 64-bit processes only. Live buffers and the pool-low-margin stay unchanged.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_POOL_SECTION_CLAMP", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "EXECUTE from max_protection for good (ml140), so every later hand-out there was born non-executable: device logs 80-83 show [pool-poison] starting exactly at such an image's allocation end, after which every process started later in the ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_PRELOAD_DLLS", title: "Load these DLLs with the D3D12 device", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Default empty. DLL names separated by ';' (e.g. xinput1_4.dll): each program loads and pins them at its first D3D12 device or probe call, while the JIT pool still has room for their copies. RDR2 loads xinput1_4.dll only at its first controller read, and on build 476 the pool was full by then: no controller and no on-screen controls. Restart the session after changing it.", choices: [], sources: ["madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_RDR2_VA_HOLD", title: "Keep 8960 MB free for Red Dead Redemption 2", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off; only with env.MADEIRA_SC_PA_POOLS = 2. 1: Social Club's layout 2 keeps libcef.dll's PartitionAlloc pools at 256 MB and its metadata at 1 GB, chrome_elf.dll's metadata at 6.25 GB, gives the rest of the app's 4 GB hold to Wine's furniture (3.75 GB more room for threads and allocations), keeps Oilpan's cage at 1 GB so the FEX arena grows to 15 GB, and holds [0x75d0000000, 0x7800000000) from boot for one 8960 MB reserve, the one Red Dead Redemption 2 makes as it starts. Set it only in that game's own file; GTA V keeps layout 2 as it is. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REPLY_OWN_WRITABLE", title: "Server replies: a writable page is written in place", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "ml2230: on (default): a server reply whose buffer lies in the JIT pool's address range but on a page that is writable at its own address (a page the pool gave up, which the system reused for a thread stack) is stored there, not through the pool's RW alias, which has no mapping for it. Before, a child process could die in its first reply (log 111: rpcss.exe, and the Steam client waited for it forever). 0: the pool's address range alone decides, as before.", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_RESERVED_REMAP", title: "Last resort for a refused window placement", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "Default on, and only on the path that already fails: when the system refuses every placement of a 32-bit program's request inside its 4 GB window (ENOMEM), the first refused range, which Wine's tables call free, is unmapped and mapped again without overwriting; if that fails the request fails as before. 0: no last resort. Read when a program starts.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_RESERVED_RETRY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "So, on a small address map only (ios_wow_small_va_slots != 0, which is 0 on a 512 GB map) and only after the MAP_FIXED itself failed with ENOMEM, the next free range of the same area is tried, at most IOS_RESERVED_RETRY_MAX times, each o...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_RESOURCE_MAP_COPY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "version queries and kept both copies until it exited; the pool ran out 1.4 s later. Set by virtual_map_section around the map, cleared by map_image_into_view for an image with a CLR header (CoreCLR maps its R2R assemblies this way and ru...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_RW_ALIAS_RETRY", title: "", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "A process without the extended-virtual-addressing entitlement has a map that ends at 0xfc0000000 (63 GB). The 0x7000000000 hint is past its end, and an ANYWHERE search that starts past the end of the map does not wrap: every alias failed...", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "env.MADEIRA_SC_GAME_CEF", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "env.MADEIRA_SC_GAME_CEF = 1 (experiment): the game keeps its libcef.dll. GTA log 2026-10-02 23:03 (file trace): GTA5_Enhanced.exe's socialclub.dll probes the Social Club files, loads libcef.dll -- refused here -- and later the helper con...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SC_IPC_SPLIT", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SC_PA_POOLS", title: "Room for Social Club's PartitionAlloc pools", kind: .choice, defaultValue: "", category: "Memory & JIT pool", note: "1: Wine boots with the emulator's arena at 0x7d00000000 (12 GB instead of 16 GB) and keeps 0x7c00000000 +4 GB free, so SocialClubHelper.exe's 32 GB PartitionAlloc reservation, which must start on a 32 GB boundary, gets 0x7800000000 (20 GB of it really reserved). 2: also libcef.dll's (0x7000000000) and Oilpan's; the JIT pool's RW alias moves to 0x7900000000. Off by default; set it in the game's own file; read at session start.", choices: [("", "Off"), ("1", "Layout 1 (chrome_elf.dll only)"), ("2", "Layout 2 (chrome_elf, libcef, Oilpan)")], sources: ["build/ntdll-unix/virtual_ios.c", "app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "env.MADEIRA_SC_RENDER_HANDLER", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SHARE_PROBE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "task #34 [share-probe]: DEFAULT-OFF (set MADEIRA_SHARE_PROBE=1). ml79: running it inline here (pre-detach, on explorer's boot thread) wedged the session — exec-at-alias hangs while the debugger is attached. Gated + deferred to a scratch ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SHARED_SECTION_EXEC", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "env.MADEIRA_SHARED_SECTION_EXEC = 1", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SHARED_SECTION_PRIVATE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0 fails the load of an image whose shared writable section is not aligned to the host page, as before; otherwise that section is mapped private.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SMALL_STACK_EXES", title: "Programs whose threads keep a 2 MB stack", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Empty by default: every thread stack is at least 8 MB (Chromium needs that). Exe names, separated by commas (e.g. RDR2.exe): threads of these programs get the stack they ask for, at least 2 MB, so their stacks take less of the shared memory space. Never list Chromium programs (SocialClubHelper.exe, Launcher.exe, steamwebhelper.exe). Read when a thread starts.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STACK_OVERFLOW_EXIT", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1310: the whole pseudo-process ends, as on Windows (idea from the published patch 0058 of another iOS port). Ending only the thread left a half-dead process behind: a browser helper without its renderer thread stays up and is never res...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SUBFLOOR_HIGH", title: "Images based just above 4 GB run through a window", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "ml2240: on (default): a 64-bit exe or DLL without relocations whose base lies between 4 GB and the start of the app's address space (an old x64 linker's default 0x100000000, which iOS never maps) is mapped elsewhere, its header names the real base, and its own preferred-base addresses are served by the fault handler and FEX, as below 4 GB. The range is used only when a fixed allocation at its first and last page is refused as outside the map. Before, such an image failed to start (c0000018; log 115: the DirectX redistributable's x64 installer helper, so a game's first-run install script stopped). 0: the 4 GB limit, as before.", choices: [], sources: ["build/ntdll-unix/signal_arm64_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SUBFLOOR_LOWENTRY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1206: 0 = a fixed-base exe starts at its real (high) entry", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SUBFLOOR_SEH", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1203: 0 = no unwind data for code at a fixed-base image's low addresses", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SUBFLOOR_VM", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1201: 0 = VirtualProtect/VirtualQuery leave fixed-base image windows alone", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_CHURN_TIGHT_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MB left before the app's memory limit below which churny sizes are tiered too (default 768, 0 = never)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_COVERAGE", title: "Swap tier coverage", kind: .choice, defaultValue: "", category: "Memory & JIT pool", note: "Which allocations the swap tier backs with its file (only when the tier is on). Large allocations (classic, the default): single 8 MB+ commits in the guest band. All allocations of 1 MB+ (blocks). 1 MB+ and overflow (wide): blocks plus allocations outside the band and fresh reservations. Whole reservations 4 MB+ (broad, ml1257): every new reservation of at least swap-min-mb (4 MB) below FEX's band backed whole when made, holes punched on decommit, swap-mb caps the disk it uses (a soft cap, checked when a block is backed). Unset: broad if swap-mode = 2, else classic.", choices: [("", "Large allocations (8 MB+)"), ("blocks", "All allocations of 1 MB+"), ("wide", "1 MB+ and overflow"), ("broad", "Whole reservations 4 MB+ (broad)")], sources: ["build/ntdll-unix/virtual_ios.c", "app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_SWAP_DONOR_ONLY", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml2200: the tier maps the donor pool only, no file", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_FILE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml2200: the tier maps the donor pool only, no file", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_HEAT", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1: [swap] heat census of re-read swap extents; 2: plus new blocks of re-read sizes stay anonymous while the footprint has room; unset/0: off", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_HEAT_FP_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "swap-heat 2: the filter pauses while the footprint is at or above this (MB, 6656)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_HEAT_MIN", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "swap-heat 2: re-reads of a block size (in two extents or more) before its new blocks stay anonymous (6)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml2200: the tier maps the donor pool only, no file", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_PUNCH_DEFER", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MADEIRA_SWAP_PUNCH_DEFER=0 keeps every swap file punch synchronous, under the virtual lock.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_RESERVE_MAX_MB", title: "Swap tier: largest reservation backed (MB)", kind: .int, defaultValue: "", category: "Memory & JIT pool", note: "The largest new reservation the swap tier backs whole: 256 MB in wide (at most 4 GB), 8 GB in broad (at most 16 GB). 9216 with broad coverage (swap-mode = 2) also backs Red Dead Redemption 2's 8960 MB heap with the file. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_TITLE_CHURN", title: "Short-lived memory of the game stays in RAM", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "On by default: a 64-bit game started beside 32-bit helpers keeps memory it frees and allocates again soon in RAM instead of the swap file, until less than MADEIRA_SWAP_CHURN_TIGHT_MB is left before the memory limit. 0: that memory goes to the donor pool or the swap file like the rest (slower once the device is out of free RAM). Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_X64_CHURN", title: "Swap tier: churn filter for 64-bit programs beside a 32-bit one", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "ml2021: off (the default) sends a 64-bit program's short-lived allocation sizes to the swap file too while a 32-bit program is in the session, instead of leaving them anonymous (the ml1258 churn filter): beside a 32-bit title the launcher chain is idle, and its anonymous pages were compressed into the footprint. 1 keeps the filter for them.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SWAP_X64_TITLE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1 (the app): the session's title is 64-bit, its 32-bit programs helpers; donor RAM first beside them", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TAIL_CARVE_EXEC_CHECK", title: "Refuse a code buffer that cannot execute", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "Default on: a new emulator code buffer whose first 16 MB hold a JIT-pool page that lost execute permission for good is refused, and the emulator asks for half the size elsewhere. 0: every buffer is granted, as before. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THIN_RESERVE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1 unread, 0 off, 1 on", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THIN_RESERVE_AFTER_GB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THIN_RESERVE_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_THREAD_STACK_SPILL", title: "New threads may use the kernel's pick when memory space is full", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: a new thread's 1 MB kernel stack (and its emulator stack) is looked for from the start of Wine's furniture band instead of from 4 GB (each new thread no longer tries about 300 refused addresses first), and when that band is full the kernel places it anywhere still free instead of the thread failing. Red Dead Redemption 2 froze four minutes into the story because every new thread failed this way while 1.8 GB was free elsewhere. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TOTAL_PHYS_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "The limit is MEASURED, not assumed: os_proc_available_memory() is what remains before jetsam, and TASK_VM_INFO.phys_footprint is what is already charged, so their sum is this process's effective total. Cached on first use so the advertis...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_USER_VA_GB", title: "Address space the game is told it has (GiB)", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "Default 0 (off): a 64-bit game is told its user address space is what the device maps. N (4-4096, never more than the real figure): it is told N GiB; only the figure changes, not placement. For a game that sizes one reservation from it and quits when it cannot get it (32 is the value to try). Logged as [user-va]. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_VA_PRESSURE_GAP_OK", title: "A slow scan through the refused hole is not pressure", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: an address-space scan that succeeded after grinding through the hole iOS refuses below the app image does not mark the address space as under pressure (which steers big reservations away from the swap tier). Read once.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_VALLOC_LOG_ALL", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Bounded. A WoW64 process lives in its own 4 GB window, so every one of its allocations carries zero_bits and lands \"above\" its 32-bit limit by design; the uncapped branch below logged each of them: 127,000 lines (22 MB of a 25 MB device ...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WARMER_SWEEP_CYCLES", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "cycles of ~2 s between the warmer's map walk and slot/window inventory (default 30; 5 = old).", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WG_64BIT", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MADEIRA: winegstreamer's unix side is bound for 32-bit (wow64) callers, and for 64-bit (ARM64EC) ones too: without it an x64 program's xWMA voices (FAudio's WMA decoder DMO, wmadmod -> winegstreamer) decode to silence. A 64-bit caller ge...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c", "build/ntdll-unix/winegstreamer_unixlib_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WIDE_USER_VA", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "device. ml124 already applied exactly this reasoning to size the ARM64EC code bitmap (\"nothing on iOS can be mapped at or above host_addr_space_limit\"); this extends the same measured ceiling to what we tell applications. * Correct on bo...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WIN32U", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Register win32u's NtUser / NtGdi syscall table in slot 1. Activating this causes user32 process_attach to crash until wineserver shared-memory bringup is complete; gated on the MADEIRA_WIN32U env var so we can flip it on for debugging.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW64_BY_TEB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Guest windows are reserved lazily; this reserves nothing unless a 32-bit main image was published or MADEIRA_WOW_PLACEHOLDERS=1 (see ios_wow_session_start). Last, after the holdback, whose first page the lowest slot borrows as its guard.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_AREA_BY_REQUEST", title: "32-bit windows: judge a merged area by the request", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "ml2220: on (default): when two adjacent guest windows' reserved areas have merged into one (a slot carved from the holdback beside slot 0), a 32-bit process's allocation is judged by the window that holds its request. Before, the first window in the merged area decided, the second process was refused its own window and failed to create its TEB (every second concurrent 32-bit process of a session). 0: as before.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_ARENA_HOLD_GB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "GB at the top of the FEX arena kept for a 32-bit program's emulator while MADEIRA_WOW_HOLD_WINDOWS is set (default 3); 0: none", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_CPU_POOL_ONLY", title: "32-bit emulator module runs from its JIT-pool copy only", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "Default on. Where the kernel lets an image become executable in place (iOS 18; iOS 26 without TXM), the 32-bit emulator module (xtajit.dll) kept an executable view beside its JIT-pool copy, and its start-up code ran in the view while the emulator was called in the copy. On: EXEC is taken back from that view once the copy exists. 0: as before. Logged as [wow-cpu-pool]. Read once per session.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_EXTRA_WINDOW", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "A launcher -> helper -> program chain needs a THIRD window. After the carve, finish the held upper half of the cage, [0x7300000000, 0x73ffff0000), on demand. The missing 64 KB and the guard are acquired together with tryfixed, which refu...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_FEX_BAND", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "madeira-bcd [wow-band]: the WOW64 CPU module (xtajit.dll) is never handed the arena (its ios_get_fex_arena unix call is unsupported), so its rpmalloc band selector asks for the whole hardware FEX band [0x7c00000000, 0x7fffffffff]. With e...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_GUARD_INSIDE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0: a 32-bit guest window reserves 4 GB plus a guard page above it, as before (default 1: the guard is the window's top page, so the 4 GB gap above stays 4 GB-aligned)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_HOLD_WINDOWS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml2020: bytes at the top of the arena the ARM64EC module's requests leave alone, for a 32-bit program that starts later in the session: its WoW64 module asks for the hardware band and nothing else, so when the 64-bit launcher chain has f...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_LIMIT_BY_WINDOW", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Guest windows are reserved lazily; this reserves nothing unless a 32-bit main image was published or MADEIRA_WOW_PLACEHOLDERS=1 (see ios_wow_session_start). Last, after the holdback, whose first page the lowest slot borrows as its guard.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_LIVE_WINDOW_GUARD", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Worker threads of the exited process can stay asleep long after its main thread is gone; their TEBs are inside the window. Keep it (the next process takes another slot) while any of them still exists. MADEIRA_WOW_LIVE_WINDOW_GUARD=0 disa...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_PRESSURE_RELEASE_MB", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "MB: when the 32-bit band has less free address space than this, idle 32-bit window placeholders are handed back (default 256); 0: never", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_RWX_PLAIN", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Unset: a 32-bit window's anonymous RWX memory is plain read/write to the host once Wine Mono's libmono-2.0-x86.dll is mapped there (ml1279/ml1282). 1: in every 32-bit window. 0: never (stores go through the JIT pool's alias, and FEX's Mono bridge stays off).", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_SPILL_CEF", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "Still nothing: a 32-bit client with several 32-bit helpers can need more windows than the band holds. [0x7400000000, 0x7c00000000) is kept for a 64-bit Chromium's PartitionAlloc pools, which a 32-bit client does not use. Spill into it to...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_STACK_FREE_OWNER", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "process's window and released that process's live memory. Device log 95: a game creating and ending a short-lived thread in a loop while the Steam client started beside it lost guest 0x167e0000+0x10000 (\"NO wine view\", then a read access...", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_STRICT_LIMITS", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WOW_WINDOW_KEEP", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "0: other programs' views may be placed inside a 32-bit guest window or its placeholder again (default 1: only the window's own process maps there)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WSEX_MINCORE", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "1: QueryWorkingSetEx's Valid bit from mincore() (iOS has no /proc pagemap); unset/0: every page reads as not resident, as before", choices: [], sources: ["build/ntdll-unix/virtual_ios.c", "madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_X18_TRAMP_ALIGN", title: "x18 trampolines on their own page", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "1 (default): an image whose .data was shifted to a 16 KB page gets its x18 trampolines on the page after it, not on its last .data page (mapped without exec). 0: the old offsets.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_X64_IMAGE_NOCOPY", title: "Pure-x64 images without a JIT-pool copy", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: an x64-only image (not ARM64EC hybrid, not a Wine builtin) in a 64-bit process is not copied into the JIT pool; the emulator runs its code from the loaded image, as 32-bit programs already do, and its executable protections are applied without EXEC. Frees the pool for hybrid DLL copies and code buffers. Hybrid images keep their copy. Set it in the game's own file; restart the session after changing it.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "exe-window-mb", title: "Executable window size (MB)", kind: .int, defaultValue: "128", category: "Memory & JIT pool", note: "The address range at 0x140000000 kept for a game exe without relocations, which can only run there. Unset: 128 MB, or for a Madeira Dock launch the size of the largest such exe in the game's folder (The Adventures of Elliot: 473 MB -> 480). The JIT pool then starts above it and is that much smaller, so a large one also needs env.MADEIRA_X64_IMAGE_NOCOPY = 1 and pool-split = 1. A number sets it (129 to 960); 128 or less keeps 128 MB. Read at launch, the game's own file wins.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "fft-arena-patch", title: "", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "ml1299: Final Fantasy Tactics - The Ivalice Chronicles: shrink its 64 GB arena to the real part of oversize-reserve-mb", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "iat-noexec", title: "", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "ml1095: madeira.cfg iat-noexec = 1", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "jumbo-keep-mb", title: "", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "ml1029: the keep floor, same units. ml1095: madeira.cfg jumbo-keep-mb = N", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "jumbo-mb", title: "", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "ml1095: madeira.cfg jumbo-mb = N", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "metal-validation", title: "", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Metal API validation for this launch (debug layer, reports instead of aborts).", choices: [], sources: ["app/Madeira/JITAllocator.c"]),
        ConfigOption(key: "oversize-reserve", title: "", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "ml1298: serve a reserve too big for the map in part (Game details > Large memory reservations)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "oversize-reserve-mb", title: "", kind: .int, defaultValue: "16384", category: "Memory & JIT pool", note: "ml1298: its real part (MB)", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "pool", title: "JIT pool size (MB)", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "madeira.cfg pool: the JIT pool size in MB (256 to 1152); wins over the size above. The game's own file wins over madeira.cfg, so a game can size the pool to fit a free run above its executable window and pair it with pool-low.", choices: [], sources: ["app/Madeira/ContentView.swift"]),
        ConfigOption(key: "pool-low", title: "JIT code buffers below the executable window", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "1: a free run below the 0x140000000 executable window (less pool-low-margin) becomes a third debugger region for the emulator's code buffers, so the whole JIT pool is left to DLL copies (GTA V: about 300 MB more). Needs the pool above the window; costs the region's size in memory. Off by default; read at launch, the game's own file wins.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-low-margin", title: "Code-buffer region: MB left free below the window", kind: .int, defaultValue: "128", category: "Memory & JIT pool", note: "With pool-low on: how much of the free run below the executable window stays free for programs that load there (child processes' main executables). A run with a free run at least this large below it keeps none. 128 by default.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-mid", title: "Split JIT pool: use the free run between the regions", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "With pool-split on: when another mapping sits between the pool's two regions and leaves a free run of 64 MB or more there, that run becomes a third debugger region in the same pool (RDR2 build 470: 604 MB pool, a 71 MB mapping and 213 MB free between the regions; the DLL copies ran out and the game failed with ERR_GFX_INIT). Only from what the two regions left of the pool size; costs that region's size in memory. Off by default (RDR2's list turns it on); read at launch, the game's own file wins.", choices: [], sources: ["app/Madeira/StikJITHelper.swift", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "pool-page-fit", title: "Fit split pool regions to memory pages", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "With pool-split on: fit regions A/B to 16 KB pages instead of 16 MB steps, retaining small remainders in free runs without increasing the requested pool budget. With pool-low on, also fit region C to pages while preserving pool-low-margin. Costs the additional pages in memory. Off by default; read at launch, the game's own file wins. Restart Madeira and enable JIT again after changing it.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-pair", title: "Split JIT pool: prefer two runs above the window", kind: .bool, defaultValue: "1", category: "Memory & JIT pool", note: "With pool-split on: the pool takes two runs above the 0x140000000 executable window when together they are larger than the single run it would get -- whether that run lies below the window, where the pool cannot split (GTA V: 368 + 320 MB instead of 464 MB), or is the higher of two runs above it (The Adventures of Elliot: 240 + 288 MB instead of 288 MB). Falls back to the single run if the placement misses. On by default; 0 turns it off. Read at launch, the game's own file wins.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "pool-split", title: "Split JIT pool around the main thread's stack", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "1: when the pool would shrink below its size (pool, 896 MB by default) because the main thread's stack splits the only executable band, the free run above the stack becomes a second debugger region and both form one pool (about 880 MB instead of 560-630 MB). Costs the second region's size in memory. Off by default; read at launch, the game's own file wins.", choices: [], sources: ["app/Madeira/StikJITHelper.swift"]),
        ConfigOption(key: "swap-images", title: "Swap tier: pure-x64 DLLs and programs in the file", kind: .bool, defaultValue: "0", category: "Memory & JIT pool", note: "Default off. 1: the sections of pure-x64 images (with env.MADEIRA_X64_IMAGE_NOCOPY = 1: libcef.dll, steamclient64.dll, launchers, the game exe) move to the swap tier's file once they are read, so they stop counting against the memory limit (iOS writes them back and may drop them). Needs swap-mb. Page edges shared with a neighbouring section stay in memory. Set it in the game's own file; read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "swap-mb", title: "Swap tier size", kind: .choice, defaultValue: "0", category: "Memory & JIT pool", note: "Moves game data to a file on this device's storage when memory runs short, up to this size. Off by default; read at launch.", choices: [("", "Off"), ("1024", "1 GB"), ("2048", "2 GB"), ("3072", "3 GB"), ("4096", "4 GB")], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "swap-min-mb", title: "Swap tier floor (MB)", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "The smallest allocation the swap tier backs (ml1257): 8 MB in classic, 1 MB in blocks and wide, 4 MB in broad unless set. MADEIRA_SWAP_MIN_KB overrides it for blocks, wide and broad.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "swap-mode", title: "Swap tier mode (2 = broad)", kind: .int, defaultValue: "1", category: "Memory & JIT pool", note: "2 selects broad swap coverage (ml1257) when env.MADEIRA_SWAP_COVERAGE is unset; any other value, classic. The coverage key wins when set.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c", "app/Madeira/Library.swift"]),
        ConfigOption(key: "swap-wow64", title: "Swap tier for 32-bit programs", kind: .choice, defaultValue: "0", category: "Memory & JIT pool", note: "ml2021: what the tier may do with memory a 32-bit program commits (inside its WoW64 guest window). Unset: donor RAM only, the memory stays ordinary RAM when the pool has none; it never goes to the swap file, which paged a 32-bit title's heap in and out of flash and froze it for seconds at a time. 1: donor RAM, then the swap file, like 64-bit programs (the old behaviour). 2: never tiered. The 64-bit launcher and helpers next to it still use the pool and the file.", choices: [("", "Donor RAM only (default)"), ("1", "Donor RAM, then the swap file"), ("2", "Never tiered (RAM only)")], sources: ["build/ntdll-unix/virtual_ios.c", "app/Madeira/Library.swift"]),
        ConfigOption(key: "swap-x64", title: "Swap tier: where 64-bit programs go first", kind: .choice, defaultValue: "0", category: "Memory & JIT pool", note: "ml2021: the stage a 64-bit program's memory takes first; the other is the fallback. Unset: the swap file while a 32-bit program is in the session (a guest window held or in use), so the kernel can evict the launcher chain's idle pages and the donor pool stays for the 32-bit program, which may not use the file; donor RAM first otherwise. 1: donor RAM first, always (the old behaviour). 2: the swap file first, always.", choices: [("", "File while a 32-bit program runs, else donor RAM"), ("1", "Donor RAM first"), ("2", "Swap file first")], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "totalphys", title: "Reported physical memory (MB)", kind: .int, defaultValue: "0", category: "Memory & JIT pool", note: "ml1095: madeira.cfg totalphys = N", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "vmwatch", title: "", kind: .text, defaultValue: "", category: "Memory & JIT pool", note: "ml1095: madeira.cfg vmwatch = 0x<hex>", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.", title: "", kind: .text, defaultValue: "", category: "Steam & Dock", note: "`env.NAME` from madeira.cfg, then the process environment. \"0\" is off.", choices: [], sources: ["app/Madeira/SwiftSteam/SteamSignIn.swift"]),
        ConfigOption(key: "env.MADEIRA_BACKGROUND_DOWNLOADS", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "On iOS 26 and later, Steam downloads continue in the background as a continued-processing task that iOS shows with its progress. 0: only the short grace period, then a clean pause until Madeira is active again.", choices: [], sources: ["app/Madeira/SteamDownloadBackground.swift"]),
        ConfigOption(key: "env.MADEIRA_BIG_PICTURE_DOCK_LIBRARIES", title: "Big Picture: every library Madeira lists", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "ml2240: on (default): Big Picture's libraryfolders.vdf gets every library Madeira's Steam list reads: the Dock client's folder, the other C: libraries its libraryfolders.vdf names and the external drives' libraries. The log names each library with its number of install records. 0: only the Dock client's folder and the external drives (ml2230).", choices: [], sources: ["app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_BIG_PICTURE_GPU", title: "Big Picture: draw the UI with the GPU", kind: .bool, defaultValue: "0", category: "Steam & Dock", note: "ml2230: 1 starts steam.exe without -cef-disable-gpu, so the web helper may draw with Chromium's ANGLE on the 32-bit D3D11 (DXMT) instead of the CPU. Off by default (software drawing, as before); a test switch.", choices: [], sources: ["app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_BIG_PICTURE_LIBRARIES", title: "Big Picture: list Madeira's Steam games", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "ml2230: on (default): before each Big Picture start, Big Picture's libraryfolders.vdf (config/ and steamapps/) gets Madeira's Steam library (the Dock client's folder) and the libraries on connected drives, beside the client's own entries, so the games Madeira installed show as installed. 0: the files are left alone.", choices: [], sources: ["app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_BIG_PICTURE_PIN", title: "Big Picture: keep the installed 32-bit client", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "ml2210: on (default): once Big Picture's folder holds the 32-bit client's web helper (bin/cef/cef.win7), steam.exe starts with -nobootstrapperupdate -skipinitialbootstrap, so it cannot move itself to the 64-bit client, whose CEF pools do not fit the address space. 0: Steam updates itself at every start, as before.", choices: [], sources: ["app/Madeira/Library.swift"]),
        ConfigOption(key: "env.MADEIRA_CEF_VERBOSE", title: "Steam web helper: verbose CEF log", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "ml2230: on (default): steamwebhelper.exe gets --enable-logging=file --v=1 --log-severity=verbose, CEF's verbose file log. 0 (the Steam Big Picture list): Steam's own log level, which saves the UI threads the writes.", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DOCK", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "`env.MADEIRA_DOCK = 0` hides Dock. Without a built dockhost.exe it is hidden too.", choices: [], sources: ["app/Madeira/MadeiraDock.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_AUTO_REVEAL", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a window that may need the user never reveals the desktop by itself (Show desktop still does)", choices: [], sources: ["app/Madeira/DockStartScreen.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_CEG", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "The install record lists per-user executables: Dock asks Valve's client to prepare them before it launches. env.MADEIRA_DOCK_CEG = 0 never asks.", choices: [], sources: ["app/Madeira/MadeiraDock.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_COMPACT_POOL", title: "", kind: .bool, defaultValue: "0", category: "Steam & Dock", note: "Opt-in per launch: a 512 MB JIT pool instead of the standard one.", choices: [], sources: ["app/Madeira/MadeiraDockView.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_GAME_SCM", title: "", kind: .text, defaultValue: "", category: "Steam & Dock", note: "1: Wine's service manager in every Dock game session, 0: never; unset: only when the prefix registers an automatic-start service outside Windows", choices: [], sources: ["app/Madeira/DockGameSession.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_GAME_SCM_SERVER_SYNC", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a session that starts the service manager keeps madsync", choices: [], sources: ["app/Madeira/DockGameSession.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_HIDE_DESKTOP", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a Dock start's starting screen ends on the desktop's first frame, as before", choices: [], sources: ["app/Madeira/DockStartScreen.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_IMAGE_MAP_GUARD", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "While the loader loads Valve's client and its many imports, the emulator's image-map handler can commit a page of its own heap under its interval lock; the commit's notification then waits for that same lock and the host parks for good (...", choices: [], sources: ["app/Madeira/MadeiraDock.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_IMAGE_RETIRE", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Valve's client unloads DLLs while it starts and the loader can map a different DLL of the same size at the same address. The engine's opt-in image-retire switch (MADEIRA_JIT_IMAGE_RETIRE, off for every other session) gives that DLL fresh...", choices: [], sources: ["app/Madeira/MadeiraDock.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALL_CHOICE", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: no per-game choice, every start runs what is pending", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALL_LAYOUT", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a session of one-time installs keeps the game's layout lines", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALL_SCM", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Installers expect a service manager, and a Dock session starts none before the host. With madsync, Wine's services.exe never answered its RPC clients in the fork's device runs, so the service step and then every installer waited; msiexec...", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALL_SEPARATE", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: the host follows the installers in the same session", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALL_SERVER_SYNC", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Installers expect a service manager, and a Dock session starts none before the host. With madsync, Wine's services.exe never answered its RPC clients in the fork's device runs, so the service step and then every installer waited; msiexec...", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALLER_REVEAL", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a one-time installer's dialog never reveals the desktop by itself", choices: [], sources: ["app/Madeira/DockStartScreen.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_INSTALLERS", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: Dock starts run no install-script programs", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_OFFLINE_LOGON", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "out a connection that cannot happen; - a note of the last online start in which Valve's client confirmed a licence and said the account can log on offline (the host's `session-offline-ready=1`), for the Game details mark. Steam's offline...", choices: [], sources: ["app/Madeira/MadeiraDock.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_RESET_CLEAN", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: Reset only forgets the records; installed files stay", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_STATUS", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: the starting screen does not watch the host's result", choices: [], sources: ["app/Madeira/DockStartScreen.swift"]),
        ConfigOption(key: "env.MADEIRA_DOCK_STEAM_RUN", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "On by default: when a game in a Madeira Dock session asks Steam to start another game (steam.exe with steam://run/<App ID>, as Black Ops II's campaign does for Zombies), steam.exe is not started and Madeira starts that game when it is next opened. 0 lets steam.exe start as before (the full Steam client, which updates itself and stops at a black window in a Dock session).", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DOCK_VULKAN_STANDIN", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: a Vulkan loader an installer wrote stays in system32", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOTNET_FUSION", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_INSTALL_SKIP_DOTNET", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "0: .NET Framework setups run too", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_DOWNLOAD_NOTIFICATIONS", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Local notifications when a Steam download finishes, fails or pauses while Madeira is in the background (permission asked at the first download). 0: none, and no permission request.", choices: [], sources: ["app/Madeira/SteamDownloadBackground.swift"]),
        ConfigOption(key: "env.MADEIRA_INSTALL_DEFAULT_KEY", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "The install scripts' programs of a game: its own folder (one level down) and the shared redistributables Steam keeps next to it, and how many scripts were read.", choices: [], sources: ["app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "env.MADEIRA_LIBRARY_COLLAPSE", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "MADEIRA_LIBRARY_COLLAPSE=0: the section titles do not collapse.", choices: [], sources: ["app/Madeira/SteamGames.swift"]),
        ConfigOption(key: "env.MADEIRA_ONBOARDING", title: "First-run Steam setup", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "`env.MADEIRA_ONBOARDING = 0` (madeira.cfg or the environment) never opens setup and hides \"Run setup again\". On by default.", choices: [], sources: ["app/Madeira/Onboarding.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_ALLOW_CRASHPAD", title: "Steam web helper: allow its crash reporter", kind: .bool, defaultValue: "0", category: "Steam & Dock", note: "ml2210: 1 (the Steam Big Picture list) lets steamwebhelper.exe start exactly one kind of child, --type=crashpad-handler, with its command line unchanged; without it the 32-bit web helper ends itself at start (crash server failed to launch). Every other --type= child stays refused. Off (default): all are refused.", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STEAM_CLOUD", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Whether Steam Cloud saves sync: Settings › Steam Cloud saves, kept in madeira.cfg as env.MADEIRA_STEAM_CLOUD (on unless it is 0; docs/STEAM_CLOUD.md). Turning it back on syncs the installed games at once.", choices: [], sources: ["app/Madeira/SteamGames.swift", "app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_CLOUD_AUTO", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "`env.MADEIRA_STEAM_CLOUD_AUTO = 0`: compare only; nothing is copied either way without the user asking on the game's page.", choices: [], sources: ["app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_CLOUD_PLAY_CHECK", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Saves that need the user's choice (count).", choices: [], sources: ["app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_CLOUD_QUIT", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "A game cannot be closed from Madeira, so its saves otherwise reach the cloud only at the next app start. The session menu's \"Upload saves and close Madeira\" sends them now: the app takes the account back from the session's client, upload...", choices: [], sources: ["app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_CLOUD_REMOTECACHE", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "`env.MADEIRA_STEAM_CLOUD_REMOTECACHE = 0`: Valve's client's remotecache.vdf is left as the client wrote it, as before SteamRemoteCache.", choices: [], sources: ["app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_LIBRARY", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "Off with `env.MADEIRA_STEAM_LIBRARY = 0`, or without Madeira Dock (a downloaded game starts through it).", choices: [], sources: ["app/Madeira/SteamOwnedLibrary.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_SIGNIN", title: "", kind: .bool, defaultValue: "1", category: "Steam & Dock", note: "`env.MADEIRA_STEAM_SIGNIN = 0` hides the sign-in button.", choices: [], sources: ["app/Madeira/SwiftSteam/SteamSignIn.swift"]),
        ConfigOption(key: "env.MADEIRA_STEAM_TRACE", title: "", kind: .bool, defaultValue: "0", category: "Steam & Dock", note: "Logging for Steam sign-in. `event` lines are the always-on, low-volume record ([steam-signin]). They never contain tokens, passwords, Steam Guard codes, account names, Steam IDs or message payloads. `trace` lines are protocol-level detai...", choices: [], sources: ["app/Madeira/SwiftSteam/Helpers/SteamLog.swift"]),
        ConfigOption(key: "alert-spin-us", title: "", kind: .int, defaultValue: "0", category: "Synchronisation", note: "ml1122: madeira.cfg alert-spin-us (default 0)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "eco", title: "Eco scheduling", kind: .bool, defaultValue: "0", category: "Synchronisation", note: "Runs guest threads at a lower iOS QoS class so the system favours efficiency and saves power; can cost speed. Class chosen by eco-qos.", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c", "app/Madeira/Library.swift"]),
        ConfigOption(key: "eco-qos", title: "Eco QoS class", kind: .choice, defaultValue: "", category: "Synchronisation", note: "The QoS class guest threads run at while eco is on.", choices: [("", "Utility (default)"), ("background", "Background"), ("initiated", "User initiated")], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "env.MADEIRA_FASTSYNC", title: "Fastsync (in-process sync, default)", kind: .choice, defaultValue: "", category: "Synchronisation", note: "Fastsync is the default engine: with neither this nor inproc-sync set, the app exports auto. Settings > Sync engine > Fastsync removes both keys. Never runs while madsync is on. auto arms the fast wake path on heavy event traffic, 1 from the start, cells only answers polls, 0 is off.", choices: [("", "Default (auto)"), ("auto", "Auto"), ("1", "On"), ("cells", "Poll answers only"), ("0", "Off")], sources: ["build/madeira_cfg.h", "wine/dlls/ntdll/unix/sync.c", "wine/server/event.c"]),
        ConfigOption(key: "env.MADEIRA_FASTSYNC_CAP_US", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "longest fast park before server_wait, 50..50000 us (2000)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "env.MADEIRA_FASTSYNC_SEM", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "1: semaphores use cells too (off by default)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c", "wine/server/event.c"]),
        ConfigOption(key: "env.MADEIRA_FASTSYNC_SPIN_US", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "adaptive spin ceiling, 0..1000 us (40); 0 = none", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "env.MADEIRA_FS_AUTO_REQS", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "auto: operations in 10 s that arm the wake path (20000, min 1000)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "env.MADEIRA_FS_POLLPEEK", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "0: no local answer to zero-timeout polls", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "env.MADEIRA_MADSYNC_SESSION", title: "", kind: .text, defaultValue: "", category: "Synchronisation", note: "Madeira Dock: the app sets MADEIRA_MADSYNC_SESSION=0 only for a session that runs a game's one-time installers first (Wine's services.exe never answered its RPC clients under madsync on device). Unset, or any other value: unchanged. Read...", choices: [], sources: ["build/madsync/madsync.c"]),
        ConfigOption(key: "inproc-sync", title: "Madsync (in-process sync)", kind: .bool, defaultValue: "0", category: "Synchronisation", note: "1 selects madsync (Settings > Sync engine > Madsync). Unset: fastsync, the default engine; 0 without env.MADEIRA_FASTSYNC: Wine standard sync.", choices: [], sources: ["build/madeira_cfg.h", "build/madsync/madsync.c", "app/Madeira/DockInstallers.swift"]),
        ConfigOption(key: "madsync-lock-spin", title: "", kind: .int, defaultValue: "256", category: "Synchronisation", note: "ml1124: the lock is held for well under a microsecond; a contended pthread_mutex_lock sleeps in the kernel (__psynch_mutexwait, ~20 us measured on average in ph-rdr74, 3.4 k times a second). Spin on trylock first. madeira.cfg madsync-loc...", choices: [], sources: ["build/madsync/madsync.c"]),
        ConfigOption(key: "madsync-spin-us", title: "", kind: .int, defaultValue: "0", category: "Synchronisation", note: "ml1122: madeira.cfg madsync-spin-us (default 0 = sleep at once)", choices: [], sources: ["build/madsync/madsync.c"]),
        ConfigOption(key: "yield-sleep-us", title: "", kind: .int, defaultValue: "100", category: "Synchronisation", note: "ml1124: madeira.cfg yield-sleep-us (default 100, 0 = never sleep), yield-streak (256)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "yield-streak", title: "", kind: .int, defaultValue: "256", category: "Synchronisation", note: "ml1124: madeira.cfg yield-sleep-us (default 100, 0 = never sleep), yield-streak (256)", choices: [], sources: ["wine/dlls/ntdll/unix/sync.c"]),
        ConfigOption(key: "d3d11", title: "Direct3D 10/11 runtime (x64)", kind: .choice, defaultValue: "", category: "Vulkan routes", note: "Unset: DXMT, Direct3D 10/11 on Metal. \"dxvk\": this session's d3d11.dll, d3d10core.dll and dxgi.dll are DXVK's (Direct3D 10/11 and DXGI on Vulkan, the bundle's vulkan/ folder), replacing DXMT for Direct3D 10/11 and DXGI; Vulkan is on (see vulkan). DXVK's DXGI only presents for Vulkan devices, so Direct3D 12 pairs with vkd3d-proton: with d3d12 unset this implies d3d12 = vkd3d. x64 programs only; read at session start; also from a game's own lines. Experimental, not device-tested.", choices: [("", "DXMT (default)"), ("dxvk", "DXVK on Vulkan")], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "d3d12", title: "Direct3D 12 runtime (x64)", kind: .choice, defaultValue: "", category: "Vulkan routes", note: "Unset: madeira-d3d12, Direct3D 12 on Metal. \"vkd3d\": this session's d3d12.dll and d3d12core.dll are vkd3d-proton's (Direct3D 12 on Vulkan, the bundle's vulkan/ folder) and Vulkan is on (see vulkan). x64 programs only; read at session start; also from a game's own lines. Not device-tested. \"1\" (ml1095, developer) runs madeira-d3d12's shader converter canary at app start.", choices: [("", "madeira-d3d12 (default)"), ("vkd3d", "vkd3d-proton on Vulkan")], sources: ["app/Madeira/ContentView.swift", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.DXVK_CONFIG", title: "DXVK options", kind: .text, defaultValue: "", category: "Vulkan routes", note: "dxvk.conf options inline, separated by ';' (e.g. dxgi.maxFrameRate=60;d3d11.cachedDynamicResources=a); applied after the config file; with d3d11 = dxvk.", choices: [], sources: []),
        ConfigOption(key: "env.DXVK_CONFIG_FILE", title: "DXVK config file", kind: .text, defaultValue: "", category: "Vulkan routes", note: "A dxvk.conf to read instead of the one in the program's working folder (a Windows path, e.g. C:\\users\\madeira\\dxvk.conf); with d3d11 = dxvk. See DXVK's dxvk.conf for the options.", choices: [], sources: []),
        ConfigOption(key: "env.DXVK_LOG_LEVEL", title: "DXVK log level", kind: .text, defaultValue: "", category: "Vulkan routes", note: "DXVK's log (none, error, warn, info, debug, trace), written to the session log through Wine's debug output. d3d11 = dxvk sets info unless this is set.", choices: [], sources: []),
        ConfigOption(key: "env.MADEIRA_DXGI_VK_SWAPCHAIN", title: "DXGI swapchains for vkd3d-proton", kind: .bool, defaultValue: "1", category: "Vulkan routes", note: "On (default): DXMT's DXGI presents for a Direct3D 12 device on Vulkan (d3d12 = vkd3d) by wrapping vkd3d-proton's swapchain (IDXGIVkSwapChainFactory); windowed only, a fullscreen request keeps the window. 0: CreateSwapChain fails with \"Unsupported device type\" for those devices, as before.", choices: [], sources: ["dxmt/src/dxgi/dxgi_swapchain_vk.cpp"]),
        ConfigOption(key: "env.VKD3D_CONFIG", title: "vkd3d-proton options", kind: .text, defaultValue: "", category: "Vulkan routes", note: "Comma-separated vkd3d-proton flags (e.g. no_upload_hvv, force_static_cbv, skip_driver_workarounds); with d3d12 = vkd3d. See vkd3d-proton's README.", choices: [], sources: []),
        ConfigOption(key: "env.VKD3D_DEBUG", title: "vkd3d-proton log level", kind: .text, defaultValue: "", category: "Vulkan routes", note: "vkd3d-proton's log: none, err, warn, fixme (default), info, trace. Passed to the Windows environment like any env line; only with d3d12 = vkd3d.", choices: [], sources: []),
        ConfigOption(key: "env.VKD3D_SHADER_DEBUG", title: "vkd3d-proton shader log level", kind: .text, defaultValue: "", category: "Vulkan routes", note: "The shader translators' log level (none, err, warn, fixme, info, trace); with d3d12 = vkd3d.", choices: [], sources: []),
        ConfigOption(key: "vulkan", title: "Vulkan library (x64)", kind: .choice, defaultValue: "", category: "Vulkan routes", note: "The Vulkan driver Wine's winevulkan loads: moltenvk = gl/libMoltenVK.dylib (the one Zink uses), kosmickrisp = gl/libvulkan_kosmickrisp.dylib, or a .dylib path (absolute or bundle-relative). Setting it turns Vulkan on for x64 programs (vulkan-1.dll and winevulkan.dll in the prefix); unset, Vulkan is off unless d3d12 = vkd3d or d3d11 = dxvk. Read at session start; also from a game's own lines.", choices: [("", "Off, MoltenVK with d3d12 = vkd3d or d3d11 = dxvk"), ("moltenvk", "MoltenVK"), ("kosmickrisp", "KosmicKrisp"), ("off", "Off")], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_ATOM_ARG", title: "Atoms in a 32-bit program's class and property names", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "Default on: a class or property name given as an atom that arrives offset by the 32-bit program's window base (inside its never-mapped first 64 KB) is taken as the atom, not read as a string pointer. 0 turns it off.", choices: [], sources: ["build/win32u-unix/class_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CHILD_DESKTOP", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Default on; 0 keeps a child without a desktop window, as before.", choices: [], sources: ["build/win32u-unix/winstation_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CLICK_FOCUS", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: a tap or click on an active window leaves its keyboard focus as it is", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DESKTOP", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "X-desktop probe: shared user32 .data means the 2nd GUI pseudo-process can resolve a NULL winproc (crash: blr NULL in call_window_proc). Log func + resolved procW for the first few calls per process.", choices: [], sources: ["build/win32u-unix/driver_ios.c", "build/win32u-unix/message_ios.c", "build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DESKTOP_FIT", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "DESKTOP FIT. A presenting window whose client area does not fit the wine desktop (a 1920x1080 window on a 1280x720 desktop) was cropped: only its top-left showed, under a title bar, which looked like a frozen, non-fullscreen game. Its Me...", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_DIRECT_CURSOR", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_DIRECT_CURSOR=0: no cursor is drawn on the game view, motion stays relative there and the pointer never locks by itself; the driver reports nothing.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_DIRECT_WINDOW_SIZE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_DIRECT_WINDOW_SIZE=1: keep an opted-in presenting window's client at the selected resolution, including an engine resize after startup. Default off; desktop sessions and ordinary windowed games are unchanged.", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_DISPLAY_SYNC", title: "Metal layer: keep display sync", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "ml2021 A/B: 1 leaves the game's Metal layer in CoreAnimation's display-sync scheduling. Off (the default) sets the private displaySyncEnabled=false (the MeloNX pattern, 2026-07-03). For a title parked 18-72 ms a frame in nextDrawable with the display link honoured at 120 Hz, this is one of the two suspects for late drawables (the other: env.MADEIRA_PROMOTE_KICK).", choices: [], sources: ["app/Madeira/ContentView.swift", "app/Madeira/FPSOverlay.swift"]),
        ConfigOption(key: "env.MADEIRA_DUMP_SURFACES", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "would be frame-to-frame change rather than corruption. That would have looked exactly like a finding. * So: a src dump arms `wph_pair`, and the very next present of any window dumps its surface under the SAME pair number. That is the tig...", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_EXTENDED_MODES", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "1: list modes up to 4x the session default's pixels", choices: [], sources: ["build/win32u-unix/sysparams_ios.c", "dxmt/src/util/wsi_monitor_headless.cpp"]),
        ConfigOption(key: "env.MADEIRA_FONT_KEYS_REPAIR", title: "Repair the registry's font list", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "On (default): a session that found no fonts leaves the registry's Fonts key alone, stale external entries that name a font of C:\\windows\\Fonts are dropped, and the Windows directory's fonts get their Fonts values back (DirectWrite lists only those, so without them embedded browsers crash and dialogs draw no text). 0: upstream Wine's font key update. Read at session start.", choices: [], sources: ["wine/dlls/win32u/font.c"]),
        ConfigOption(key: "env.MADEIRA_FOREGROUND_FIX", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: never make the game's main window foreground", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FPS_CAP", title: "Fixed frame cap (fps)", kind: .int, defaultValue: "", category: "Windows, display & input", note: "Unset (default): no cap beyond the FPS limit. 10-120: frames start at most N times a second for the whole session: a Direct3D 12 game's thread waits after each Present, a DXMT game's encode thread before each present (a timed kernel wait, not a spin). Any value, e.g. 20 or 24, unlike the FPS limit's 30/40/60; the lower of the two applies. While it is set, env.MADEIRA_FPS_GOV_MW is ignored. Needs the [xp] sampler (MADEIRA_PROBES not 0). Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c", "madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_FPS_COUNT_HIDDEN", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "1: the FPS readouts count hidden windows' presents too (as before 2026-10-26)", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_FPS_GOV_BAND_MJ", title: "Frame-cap governor: energy band (mJ)", kind: .int, defaultValue: "1500", category: "Windows, display & input", note: "Only with env.MADEIRA_FPS_GOV_MW set: how much energy the running balance may drift above or below the target before the cap moves one step (100-100000; unset or out of range: 1500). Smaller moves the cap sooner and more often. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FPS_GOV_MAX", title: "Frame-cap governor: highest cap (fps)", kind: .int, defaultValue: "60", category: "Windows, display & input", note: "Only with env.MADEIRA_FPS_GOV_MW set: the highest frame cap the governor uses, the largest of 60, 40, 30, 24 and 20 at or below this value (20 when lower). Unset: 60. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FPS_GOV_MIN", title: "Frame-cap governor: lowest cap (fps)", kind: .int, defaultValue: "20", category: "Windows, display & input", note: "Only with env.MADEIRA_FPS_GOV_MW set: the lowest frame cap the governor goes down to, the smallest of 60, 40, 30, 24 and 20 at or above this value, never above the highest cap. Unset: 20. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FPS_GOV_MW", title: "Hold CPU power with a frame cap (mW)", kind: .int, defaultValue: "", category: "Windows, display & input", note: "Unset (default): off. N: while the game presents, the process's CPU power ([xp]'s energy) is held at N mW on average by moving a frame cap between 60, 40, 30, 24 and 20 fps (at most one step per 3 s; held while nothing presents). Unlike env.MADEIRA_POWER_GOV_MW it moves no thread to the efficiency cores. Menus and loading at 3-4 W fill the budget after which iOS clamps the CPU; e.g. 1500 keeps a 60 fps menu near 30-40 fps. [fps-gov] lines every 10 s. env.MADEIRA_FPS_GOV_MIN / _MAX (20 / 60) bound the cap, _BAND_MJ (1500) is the energy the average may drift before it moves. Needs the [xp] sampler. Read at session start.", choices: [], sources: ["build/ntdll-unix/server_ios.c", "madeira-d3d12/src/pe/madeira_d3d12.c"]),
        ConfigOption(key: "env.MADEIRA_FRAME_TIMES", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: no frame-time marks; the overlay's graph and 1% cells stay empty", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_FULLSCREEN_FOREGROUND", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: a full-screen window shown with activation is left to the foreground lock", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GAME_DIALOG_CURSOR", title: "Cursor over a game's launcher or message box", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "Default on. A game session draws no cursor: the finger is the pointer. While the game shows a launcher or message box, the arrow is drawn where the finger last touched (where the click lands) and goes away with the box. Tap the button itself to press it. 0: no cursor, as before. Desktop (Dock) sessions keep their own cursor.", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_GAME_INPUT_WAKE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Default on: a launcher / message box over a game takes taps and keys; 0 = off.", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GAME_WINDOWS", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Game-mode windows. Outside desktop mode a window got win32u's offscreen surface and its position never reached the app, so a launcher or a message box a game opens before (or instead of) its 3D window was drawn nowhere: a game's Play / O...", choices: [], sources: ["build/win32u-unix/driver_ios.c", "app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_GDI_SECTION_ALWAYS", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "upstream's anonymous allocation -- and any 32-bit program started LATER in such a session (a 64-bit launcher's 32-bit child, or the app's in-session launcher starting the 32-bit Steam client into an explorer desktop) kept the host table ...", choices: [], sources: ["wine/dlls/win32u/gdiobj.c"]),
        ConfigOption(key: "env.MADEIRA_GDI_SHARED_SECTION", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "was armed for 32-bit code when win32u initialised, so a 64-bit session kept upstream's anonymous allocation -- and any 32-bit program started LATER in such a session (a 64-bit launcher's 32-bit child, or the app's in-session launcher sta...", choices: [], sources: ["wine/dlls/win32u/gdiobj.c"]),
        ConfigOption(key: "env.MADEIRA_GL_BACKEND", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "With the GLES backend there is no desktop GL context, so make LOVE ask for OpenGL ES first. LOVE 11 checks this SDL hint (read from the environment) before trying desktop GL; SDL then creates the context through WGL_EXT_create_context_es...", choices: [], sources: ["build/win32u-unix/opengl_ios.c", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_GL_COMPILE_TIMEOUT", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "seconds a Metal shader compile may take under Zink (default 20); then the shader fails and its draws are skipped. 0: no limit", choices: [], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GL_DIR", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Load OSMesa and prove Zink actually runs: a throwaway core-profile context must report the Zink renderer. Mesa quietly falls back to softpipe when Zink cannot start (no MoltenVK, missing Vulkan features), and a software rasterizer is not...", choices: [], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GL_FPS_CAP", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: OpenGL games ignore the session's FPS limit, as before", choices: [], sources: ["app/Madeira/Winios/WiniosGL.m"]),
        ConfigOption(key: "env.MADEIRA_GL_PERF", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: no GL perf line (presents/s, flush-ms ...) and no ml1341 stall reports", choices: [], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GL_SHADER_CACHE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: no Mesa shader disk cache for desktop OpenGL (Zink); every run converts and compiles all shaders again", choices: [], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_GL_VULKAN", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Vulkan driver for Zink when madeira.cfg gl-vulkan is unset: moltenvk (default), kosmickrisp, or a .dylib name/path", choices: [], sources: ["build/win32u-unix/opengl_ios.c"]),
        ConfigOption(key: "env.MADEIRA_HIDDEN_LAYER_FPS", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "frames a second a hidden desktop window's Metal layer may present (default 10); 0 = no limit", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_HWINPUT", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_HWINPUT=0: no keyboard/mouse bridging, no pointer recognisers, no touch filter, no drawn cursor; the app behaves as it did before this file existed.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_INPUT_FOCUS", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_INPUT_FOCUS=0: keyboard and mouse reach the program whatever has focus (the program still gets nothing while the app is inactive: held input is released then).", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_INPUT_FOREGROUND", title: "Bring the game to the front when no window is", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "Default off. iOS has no window manager: a game that shows its window without activating it and reads no XInput stays in the background, and Windows sends raw keyboard and mouse input only to the program in front (Horizon Zero Dawn ignored every key and tap). 1: while no window at all is in front, the game's main window is brought to the front when it polls its messages or a key or tap arrives. Never while another window is in front.", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_KMT_ADAPTER", title: "D3DKMT adapter for the GPU (WDDM 3.1)", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "1: D3DKMTEnumAdapters2 lists the GPU DXGI and D3D12 report (same LUID) and D3DKMTQueryAdapterInfo answers like a WDDM 3.1 driver (driver version, caps, device ids, memory, performance data). Off (default): no adapter is listed, as before. Read at session start.", choices: [], sources: ["build/win32u-unix/d3dkmt_ios.c"]),
        ConfigOption(key: "env.MADEIRA_KMT_TRACE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "The [vkmt] entry-point trace; MADEIRA_KMT_TRACE=0 turns it off.", choices: [], sources: ["build/win32u-unix/d3dkmt_ios.c"]),
        ConfigOption(key: "env.MADEIRA_METAL_HUD_MAIN", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "1: Apple's Metal HUD only on the largest shown desktop window's Metal layer (its main layer), off on the other layers; default: Apple's own choice", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_MOUSE_ROUTING", title: "Mouse routing and pointer-lock fixes", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "Default on. 0 restores the previous desktop cursor routing, mouse button callbacks, surface-touch handling and key-window-only pointer lock. Keyboard input and manual Ctrl+Alt+P remain available. Fully restart Madeira after changing this switch.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_NAV_KEYS_E0", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Wine's own UI never noticed, because dialogs read the VK out of wParam. A GAME does notice: Unity reads the keyboard through raw input and DirectInput identifies keys by scan code (DIK_W is 0x11, not 'W'), so W/A/S/D were delivered, acce...", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_OPENGL", title: "OpenGL through Mesa on D3D12", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "On: x64 games get Mesa's opengl32.dll (OpenGL 3.3 on D3D12, then Metal) when build/mesa-d3d12/build.sh has put it in the app. 0: Wine's builtin opengl32, which uses the native WGL OpenGL ES/Zink route. A game folder's own opengl32.dll still wins. Read at session start.", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_PAD_KBM", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "Availability of the mode. 0 removes the per-game choice; the physical pad then always feeds XInput.", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PASTE_INTERVAL_MS", title: "Clipboard typing interval (ms)", kind: .int, defaultValue: "10", category: "Windows, display & input", note: "Default 10 ms between pasted characters. Range 1-100 ms; use a longer interval for games that miss fast text input. Enforced at delivery as well as queueing. Restart the session after changing it.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_POINTER_ABSOLUTE", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_POINTER_ABSOLUTE=0: the program's cursor never follows the iOS pointer's position; all motion is relative.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_POINTER_AUTOLOCK", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_POINTER_AUTOLOCK=0: the pointer locks only on request, not while the program hides its cursor (see `AutoLock`).", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_POINTER_HIDDEN_ABSOLUTE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_POINTER_HIDDEN_ABSOLUTE=1 (a game's own config): the program's cursor follows the iOS pointer's position even while it hides the Windows cursor, and the pointer never locks by itself. For a game that hides the cursor only to draw...", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_POINTER_LOCK", title: "", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "MADEIRA_POINTER_LOCK=0: the pointer is never locked and no lock button or chord is offered.", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_PROMOTE_KICK", title: "Display link: commit a transaction per tick", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "ml2021 experiment: 1 adds a one-pixel layer whose opacity alternates on every display-link tick, so each tick commits a CoreAnimation transaction. For a title parked 80 ms a frame in nextDrawable with the 120 Hz link armed: if the waits fall with this on, the compositor needed a transaction, not an intent.", choices: [], sources: ["app/Madeira/FPSOverlay.swift"]),
        ConfigOption(key: "env.MADEIRA_RESTORE_BORN_MINIMIZED", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: while a Dock start's census runs, a window first shown minimized stays minimized", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_RESTORE_BORN_MINIMIZED_LATE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "0: a window first shown minimized after a Dock start's starting screen has ended stays minimized", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_SCREEN_H", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau...", choices: [], sources: ["build/win32u-unix/sysparams_ios.c", "dxmt/src/util/wsi_monitor_headless.cpp", "wine/server/winstation.c"]),
        ConfigOption(key: "env.MADEIRA_SCREEN_SRC", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau...", choices: [], sources: ["build/win32u-unix/sysparams_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SCREEN_W", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau...", choices: [], sources: ["build/win32u-unix/sysparams_ios.c", "dxmt/src/d3d9/d3d9_device.cpp", "dxmt/src/util/wsi_monitor_headless.cpp"]),
        ConfigOption(key: "env.MADEIRA_SURF_SENTINEL", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "them, and I reported the first as settled when the data did not support it. * Fix: after each flush, stamp every currently-zero pixel with a sentinel. That leaves NO zero pixels behind, so the next flush classifies every pixel with no bo...", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_SURF_SEQ", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "Also drives MADEIRA_SURF_SEQ: bursts of N CONSECUTIVE frames, so the black regions that change every frame can be measured frame-to-frame offline. The 2s-throttled first/latest dump structurally cannot show that. Dirty rect goes in the f...", choices: [], sources: ["app/Madeira/Winios/Winios.m"]),
        ConfigOption(key: "env.MADEIRA_TINY_WINDOW_FIX", title: "Size a tiny game window to the screen", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "Default off. 1: a window a swapchain presents into whose client area stays under 160x120 for 3 seconds while the swapchain draws 320x200 or more is sized to the virtual screen (at most twice per window). Needs a desktop (Dock) session. Logged as [tiny-win]. Read at session start.", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TOUCH_XINPUT", title: "Touch controller as XInput player 1", kind: .text, defaultValue: "", category: "Windows, display & input", note: "", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "env.MADEIRA_VDCFG_PATH", title: "QueryDisplayConfig lists the monitor's path", kind: .bool, defaultValue: "0", category: "Windows, display & input", note: "Default off: success with no path, as before. 1: QueryDisplayConfig returns the virtual monitor's one path (source and target mode, the desktop size) and DisplayConfigGetDeviceInfo names its source, target and adapter, for a game that builds its fullscreen window from the paths.", choices: [], sources: ["build/win32u-unix/sysparams_ios.c"]),
        ConfigOption(key: "env.MADEIRA_VIRTUAL_MODE_SET", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "MADEIRA_VIRTUAL_MODE_SET=0: accept a listed mode without programming it -- the monitor keeps the session default size, as before this change.", choices: [], sources: ["build/win32u-unix/sysparams_ios.c"]),
        ConfigOption(key: "env.MADEIRA_VK_HOST_SUBOPTIMAL", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "The host surface can measure its size in other units than the client rect (an iOS CAMetalLayer reports points), so the host may call a swapchain suboptimal although it matches the window's client rect. The application cannot fix that: a ...", choices: [], sources: ["wine/dlls/win32u/vulkan.c"]),
        ConfigOption(key: "env.MADEIRA_VMON_IDS", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "synthesized branch; DXGI_OUTPUT_DESC::DeviceName says the same), and one monitor under it, the virtual monitor, which has no source. Upstream's code gives a sourceless monitor the GDI name \"WinDisc\" -- Windows' name for a DISCONNECTED di...", choices: [], sources: ["build/win32u-unix/sysparams_ios.c"]),
        ConfigOption(key: "env.MADEIRA_VULKAN_LIBRARY", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "", choices: [], sources: ["build/win32u-unix/vulkan_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WINDOW_LINEAGE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "1: report window lineage to the desktop compositor (off by default; this app's hook is a stub)", choices: [], sources: ["build/win32u-unix/driver_ios.c"]),
        ConfigOption(key: "env.MADEIRA_WINPROC_HANDLE", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "", choices: [], sources: ["build/win32u-unix/class_ios.c"]),
        ConfigOption(key: "env.MADEIRA_XCTEST_TYPING", title: "", kind: .text, defaultValue: "", category: "Windows, display & input", note: "True while a hardware keyboard delivers raw key events. The text bridge (MetalBackedView's UIKeyInput) receives the same presses from UIKit, so it stands aside while this is true instead of typing every key twice. An explicit test sessio...", choices: [], sources: ["app/Madeira/HardwareInput.swift"]),
        ConfigOption(key: "env.MADEIRA_XINPUT", title: "Physical controllers (XInput)", kind: .bool, defaultValue: "1", category: "Windows, display & input", note: "ml1930: physical and touch controller snapshots share the same serial publisher. Slot/profile/timer state belongs exclusively to `queue`. The app lifecycle and observer registration belong to the main actor. Guest readers use the C snaps...", choices: [], sources: ["app/Madeira/GamepadInput.swift"]),
        ConfigOption(key: "cpu-count", title: "Reported CPU count (0 = device)", kind: .int, defaultValue: "0", category: "Wine core (ntdll)", note: "(experiment: RDR2 sizes its job system from it; iPhone = 2 P + 4 E cores).", choices: [], sources: ["wine/dlls/ntdll/unix/system.c"]),
        ConfigOption(key: "env._JAVA_OPTIONS", title: "Java runtime options", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Passed into the game's environment and read by a bundled Java runtime (e.g. -XX:-UseZGC to leave a garbage collector off that cannot map its heap here).", choices: [], sources: []),
        ConfigOption(key: "env.DOTNET_EnableWriteXorExecute", title: ".NET runtime: W^X mapping", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Passed into the game's environment and read by the .NET (CoreCLR) runtime itself. 0 turns off its write-xor-execute double mapping of JIT code, for a .NET game whose JIT stops at start.", choices: [], sources: []),
        ConfigOption(key: "env.DOTNET_GCRegionRange", title: ".NET runtime: GC region reservation", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Passed into the game's environment and read by the .NET runtime: the size (hex bytes) of the address range its regions GC reserves at start, for a .NET game whose default reservation fails.", choices: [], sources: []),
        ConfigOption(key: "env.LC_ALL", title: "Wine's locale for this game", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Empty: Wine takes the user locale from the device's language. en_US.UTF-8 gives the game an English system and user locale, for a game that fails right after loading a non-English OEM code page. Read at session start.", choices: [], sources: []),
        ConfigOption(key: "env.MADEIRA_AFD_EVENT_HANDLE", title: "", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "", choices: [], sources: ["wine/dlls/ntdll/unix/socket.c"]),
        ConfigOption(key: "env.MADEIRA_APP_DLL_SHADOW", title: "Ignore these DLLs in the game's folder", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Default empty. DLL names separated by ';' (e.g. vcruntime140.dll): a plain x64 copy of one of them outside C:\\windows (the game's own folder) is reported as not loadable, so the loader binds the system's, as it already does for ucrtbase.dll. For a game that ships Microsoft's x64 vcruntime140.dll but not msvcp140.dll: Wine's msvcp140 cannot call that x64 copy (Crysis 3 Remastered: \"MSVCP140.dll failed to initialize\", c000001d). Logged as [app-dll-shadow]. Read at every DLL load.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_BG_QOS_DELAY_S", title: "", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "seconds the game must present before the listed processes are demoted (default 60)", choices: [], sources: ["build/ntdll-unix/server_ios.c"]),
