        ConfigOption(key: "env.MADEIRA_KEYED_EVENT_PER_PROCESS", title: "A default keyed event per process", kind: .bool, defaultValue: "1", category: "Wine core (ntdll)", note: "On (default): each Windows process gets its own keyed event for the waits and wakes that pass no handle (RtlRunOnce among them), created on first use. 0: every process uses the one the first process created, as before, whose handle is not valid in the others (Slay the Spire 2 failed in RtlRunOnceComplete). Read once per app run.", choices: [], sources: ["build/ntdll-unix/loader_ios.c"]),
        ConfigOption(key: "env.MADEIRA_LOCK_ORPHAN", title: "Orphan-lock reaper mode", kind: .choice, defaultValue: "", category: "Wine core (ntdll)", note: "Default and stamped: only a lock seen held by FEX can be released, after three monitor cycles with the same lock word and no live owner stamp. Guest locks are never released. 0: no orphan-lock releases. The dead-thread reaper is unchanged. Restart the session after changing it.", choices: [("", "Only stamped locks (default)"), ("stamped", "Only stamped locks"), ("0", "Off")], sources: ["wine/dlls/ntdll/unix/sync.c"]),
