        ConfigOption(key: "env.MADEIRA_SC_CEF", title: "Social Club's Chromium in one process", kind: .bool, defaultValue: "1", category: "Wine core (ntdll)", note: "On by default; 0 turns it off. SocialClubHelper.exe runs --single-process with PartitionAllocBackupRefPtr disabled and V8 --jitless (MADEIRA_JITLESS = 0 keeps V8's JIT), its --type= children are refused, and a process with socialclub.dll mapped that is not the helper (the game) gets no JIT-pool copy of libcef.dll: its load fails, as it did when the pool was full. No effect on programs without Social Club.", choices: [], sources: ["build/ntdll-unix/process_ios.c", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SC_CEF_FLAGS", title: "Extra SocialClubHelper.exe switches", kind: .text, defaultValue: "", category: "Wine core (ntdll)", note: "Appended verbatim to SocialClubHelper.exe's command line while env.MADEIRA_SC_CEF is on, e.g. --disable-gpu or --enable-logging=file --v=1. A --js-flags= in it gets --jitless as its first flag (Chromium keeps only the last --js-flags=), unless MADEIRA_JITLESS = 0.", choices: [], sources: ["build/ntdll-unix/process_ios.c"]),
