        ConfigOption(key: "env.MADEIRA_MFC", title: "Microsoft MFC (mfc140.dll, mfc140u.dll)", kind: .bool, defaultValue: "1", category: "Wine libraries", note: "On by default. MFC comes from the same Microsoft VC++ package as the C++ runtime and is linked into the game's system32; games that import it (Horizon Zero Dawn) stop at once without it. Wine has no MFC of its own. 0 leaves it out. Read at session start.", choices: [], sources: ["app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_MONO_DEFAULTS", title: "", kind: .text, defaultValue: "", category: "Wine libraries", note: "Wine Mono, 32- and 64-bit: mscoree sets MONO_THREADS_SUSPEND=coop and adds keep-delegates to MONO_DEBUG before Mono loads, and puts the previous values back once Mono has read them (ml1282); values already set win. 0 sets nothing.", choices: [], sources: ["wine/dlls/mscoree/metahost.c"]),
        ConfigOption(key: "env.MADEIRA_NSI_DEVICE_CACHE", title: "", kind: .text, defaultValue: "", category: "Wine libraries", note: "On by default: without \\\\.\\Nsi, the failed open is remembered instead of being retried on every call. 0 retries every time.", choices: [], sources: ["wine/dlls/nsi/nsi.c"]),
        ConfigOption(key: "env.MADEIRA_NSI_NOTIFY_PENDING", title: "", kind: .text, defaultValue: "", category: "Wine libraries", note: "On by default: without \\\\.\\Nsi, an address-change request stays pending (the addresses do not change) instead of failing at once. 0 fails it as before.", choices: [], sources: ["wine/dlls/nsi/nsi.c"]),
        ConfigOption(key: "env.MADEIRA_SCM_ON_DEMAND", title: "Start the service manager when a program needs it", kind: .bool, defaultValue: "1", category: "Wine libraries", note: "ml2270: on (default): when a 64-bit program opens the service manager and services.exe is not running (the session did not start Windows services first), sechost starts it once per process, waits up to 20 s for its pipe and asks again. Before, the call failed: a game from another store whose first start runs a launcher installer could not register the launcher's service and the installer stopped (testers' logs, 2026-10-28: a publisher's launcher installer run by an Epic copy's first start). 0: as before.", choices: [], sources: ["wine/dlls/sechost/service.c"]),
        ConfigOption(key: "env.MADEIRA_SETUPAPI_MEDIA_FIX", title: "", kind: .text, defaultValue: "", category: "Wine libraries", note: "Madeira ml1310: ask for the media again only when the answer named a new place to look. An unattended install's callback (the default one included) answers \"same place\" forever, and the loop never ended; report a copy error instead. Idea...", choices: [], sources: ["wine/dlls/setupapi/queue.c"]),
        ConfigOption(key: "env.MADEIRA_ZERO_MITIGATION_POLICY", title: "", kind: .text, defaultValue: "", category: "Wine libraries", note: "uninitialised PROCESS_MITIGATION_CONTROL_FLOW_GUARD_POLICY, and when EnableControlFlowGuard (bit 0) happens to be set it looks up SetProcessValidCallTargets in api-ms-win-core-memory-l1-1-3.dll, which this Wine does not export, and calls...", choices: [], sources: ["wine/dlls/kernelbase/process.c"]),
        ConfigOption(key: "env.MADEIRA_CLIP_NOTIFY_ALWAYS", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "1: notify the foreground thread on every ClipCursor, as before", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_CTX_FRAME", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "a live mirror, which is why four of five stalled threads reported rip=0. * Selector mirrors is_inside_syscall() exactly: kernel_stack <= sp <= syscall_frame. NOT \"native pc is not EC\" -- FEX JIT code is also non-EC but its frame may be s...", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_DEAD_RELEASE", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "getenv once, not per release", choices: [], sources: ["wine/server/object.c"]),
        ConfigOption(key: "env.MADEIRA_ILONLY_WOW64", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "Kill switch, read once: 0 turns the check off.", choices: [], sources: ["build/wineserver/mapping_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REAL_SUSPEND", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "Read on every call: the app sets it per session (a game's \"Pause threads fully\" switch, BCDLaunch.realSuspend), and this server runs again in the same process for the next session of the app run. Logged when it changes.", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REGFLUSH_SAVE", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "MADEIRA_REGFLUSH_SAVE=0: RegFlushKey does nothing again; the registry is saved periodically and at exit (ml1310)", choices: [], sources: ["build/wineserver/request_ios.c"]),
        ConfigOption(key: "env.MADEIRA_REPLACE_READONLY_LINK", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "On by default: an overwrite (supersede, overwrite, overwrite-if) through a link to a read-only file replaces the link with a new file. 0 fails it with access denied.", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_DIRECT", title: "Run simple server requests on the calling thread", kind: .text, defaultValue: "0", category: "Wine server", note: "Default off. 1: the Wine server's simplest requests (opening files and their descriptors, closing handles, mappings looked up, registry keys and values, events, semaphores, mutexes, completion ports) run on the thread that asks, under the server's lock, instead of a round trip through a pipe to the server thread: no thread switches, and the work runs on the asking thread's core. 2: waits (select), timers and set_cursor too. Every other request goes through the pipe as before. Horizon Zero Dawn's menu sends ~7000 requests a second. Read at each launch.", choices: [("", "Off (default)"), ("1", "Files, handles, registry, events, semaphores"), ("2", "Also waits, timers and the cursor")], sources: ["build/wineserver/request_ios.c", "build/wineserver/fd_ios.c", "build/ntdll-unix/server_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_DOORBELL", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "0: read every client fd on every pass, as before", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_ECO_FOLLOW", title: "Server thread follows ECO", kind: .bool, defaultValue: "0", category: "Wine server", note: "Default off. 1: while ECO is on, the Wine server thread runs at utility QoS (ECO's default class) instead of user-interactive, so it moves to the efficiency cores with the game's threads, and back when ECO goes off. In Horizon Zero Dawn's menu with eco = 1 the server was the only thread left on a performance core (0.54 cores at ~3.9 GHz). Server requests may take longer. Read at each launch.", choices: [], sources: ["build/wineserver/fd_ios.c", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_SRV_FD_SOCKET", title: "File descriptors through the process socket", kind: .bool, defaultValue: "0", category: "Wine server", note: "Kill switch, default 0: a file's descriptor comes back in the server's get_handle_fd reply (a copy the server makes; it shares this process's descriptor table), the same descriptor without a sendmsg, a recvmsg, an fcntl and two server log lines per file. 1: through the process socket, as before. Read once per app run.", choices: [], sources: ["build/ntdll-unix/server_ios.c", "build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_FULLSCAN_MS", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "ms between reads of every client fd with the doorbell on (default 10)", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_IDLE_US", title: "Server loop's longest sleep (us)", kind: .int, defaultValue: "1000", category: "Wine server", note: "Default 1000 (1 ms, as before); 100 to 50000. Requests and timers wake the Wine server at once; only its socket polls and fd scans wait for this tick, so a longer one means fewer server wake-ups while idle (1000 a second at the default) and slower readiness of network sockets and pipes. Mostly useful with env.MADEIRA_SRV_DIRECT. Read at each launch.", choices: [], sources: ["build/wineserver/fd_ios.c", "app/Madeira/WineProcessBridge.m"]),
        ConfigOption(key: "env.MADEIRA_SRV_LOG_ALL", title: "Every per-descriptor server log line", kind: .bool, defaultValue: "0", category: "Wine server", note: "Kill switch, default 0: the Wine server's add_poll_user and send_client_fd log lines (one per opened file or descriptor sent, each a formatted write to the log file on the server thread) are written for their first 64 and then every 1000th; a failed send is always written. 1: every line, as before. Read at each launch.", choices: [], sources: ["build/wineserver/fd_ios.c", "build/wineserver/request_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_NOSEM", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "zero, semaphore_timedwait returns instantly forever, and the loop stops sleeping — ml584 measured 2,935 iter/s against a 1 ms floor that caps it at ~1,000/s. * This gate changes ONLY the wait mechanism. sleep_ns is computed identically a...", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_POLL_US", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "us between socket polls and fd scans with the doorbell on (default 1000, 0 every pass)", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_SRV_WAKE_COALESCE", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "0: one wake signal per request, as before", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STORAGE_DEVICE", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "0: no \\\\.\\\\PhysicalDrive0 (the prefix disk's capacity)", choices: [], sources: ["build/wineserver/storage_device_ios.c"]),
        ConfigOption(key: "env.MADEIRA_STUCK_WAIT_SECS", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_TIMER_FAIRNESS", title: "Timers run while a window keeps repainting", kind: .bool, defaultValue: "1", category: "Wine server", note: "Default on. A thread gets its paint messages before its timers, so a window that invalidates itself while it paints starved every timer of that thread for good: the Rockstar Games Launcher installer, whose status text and finish page run on a timer, stayed at \"Preparing to Install...\" after its work was done. A timer that has waited 100 ms now goes before such a paint. 0: the strict order, as before. Read once per app run.", choices: [], sources: ["build/wineserver/queue_ios.c"]),
        ConfigOption(key: "env.MADEIRA_USD_TIME", title: "", kind: .text, defaultValue: "", category: "Wine server", note: "The same frozen page makes every \"N ms have passed since X\" test in a guest false for the life of the process: a headless host that sits online and re-checks a condition \"5 s after sign-in\" never reaches its check, and its own 90 s wall-...", choices: [], sources: ["build/wineserver/fd_ios.c"]),
        ConfigOption(key: "no-local-read", title: "", kind: .bool, defaultValue: "0", category: "Wine server", note: "ml1095: madeira.cfg no-local-read = 1", choices: [], sources: ["build/wineserver/mach_ios.c"]),
        ConfigOption(key: "env.MADEIRA_ARENA_TEST", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "", choices: [], sources: ["FEX/Source/Windows/Common/ArenaSelfTest.cpp"]),
        ConfigOption(key: "env.MADEIRA_BLOCK_RING", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "ml1205: the block-entry ring, when MADEIRA_BLOCK_RING is set (32 KB per thread, never freed).", choices: [], sources: ["FEX/FEXCore/Source/Interface/Core/Core.cpp", "FEX/FEXCore/Source/Interface/Core/JIT/JIT.cpp"]),
        ConfigOption(key: "env.MADEIRA_CALLRET_RESET_RATE", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "MADEIRA: rate-limit the call-ret reset that follows a code invalidation. * On the iOS host nothing reads the stack's contents: the RET shortcut (BranchOps.cpp, ml305) and the EnterEC return (Dispatcher.cpp) are compiled out, so a skipped...", choices: [], sources: ["FEX/FEXCore/Source/Interface/Core/Core.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_AVX", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "iOS-Madeira: MADEIRA_FEX_AVX=2, AVX without AVX2 (see HideAVX2 in CPUID.h). Exactly \"2\"; \"1\" and unset are unchanged.", choices: [], sources: ["FEX/FEXCore/Source/Interface/Core/CPUID.cpp", "FEX/Source/Windows/Common/CPUFeatures.cpp", "build/ntdll-unix/virtual_ios.c"]),
        ConfigOption(key: "env.MADEIRA_FEX_BRANCH_HISTORY", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "Recorder emitted only for this executable, before CTX/JIT creation.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_CALLRET_ELIDE", title: "64-bit JIT without the call-return shadow stack", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "Default on. The 64-bit (ARM64EC) JIT no longer keeps FEX's call-return shadow stack, which nothing reads on iOS: 9 instructions less per guest CALL and per RET, and linked calls become `bl`, so the CPU's return predictor follows guest calls. 0: the stack as before. Read when a program starts.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_BITMAP_CACHE", title: "Native-code check with the thread's bitmap pointer", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "Default on. The 64-bit JIT's dispatcher tests the native-code bitmap through a pointer kept in the thread's state instead of walking TPIDRRO_EL0, the TEB and the PEB: 4 instructions less on every call into a system DLL through its import table. 0: the walk as before. Read when a program starts.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_EXIT_LEAN", title: "Lean exit from the JIT into native code", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "Default on while AFP is off (the default). Calls from the 64-bit JIT into native (ARM64EC) code use a shorter stub: no FPCR read, the CPU area and suspend doorbell from the thread's state, the call counted per thread instead of with an atomic, and the alias lookup starting at the thread's own last hit; 31 instructions instead of 44. [xp-api] x64->EC rates lag by under 64 calls per thread. 0: ExitFunctionEC as before. Read when a program starts.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_RET", title: "Returns from native code through the return predictor", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "Default on. A guest call into native (ARM64EC) code leaves the JIT with BLR and its return comes back with RET after an L1 lookup (10 instructions instead of 22), so the CPU's return-address predictor stays in step with the guest's calls. 0: BR and the dispatcher loop as before. Read when a program starts.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_EC_RET_DIRECT", title: "Returns from native code straight into the JIT", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "Default on. When a native (ARM64EC) function returns to the game's x64 code, the return enters the 64-bit JIT at once instead of testing the native-code bitmap first; the JIT's dispatcher already tests every address it has no translation for. 11 instructions less per return from a system DLL. 0: the test as before. Read when a program starts.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_FAIL_CALLRET", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "MADEIRA_FEX_FAIL_CALLRET=threadstate:N fails the Nth thread-state allocation, so this containment path can be proven rather than assumed -- it only occurs naturally once the band is exhausted.", choices: [], sources: ["FEX/FEXCore/Source/Interface/Core/Core.cpp", "FEX/Source/Windows/Common/CallRetStack.h"]),
        ConfigOption(key: "env.MADEIRA_FEX_PRELOADED_IMAGES", title: "FEX: record images loaded before it starts", kind: .bool, defaultValue: "1", category: "x86 emulation (FEX)", note: "ml2260: on (default): when FEX starts in a 64-bit process it records the code sections of every image already loaded (kernel32, kernelbase, ucrtbase are mapped for it before its notifications work). Before, their x64 export thunks were not known as code: a 64-bit x64 program's call into one ended it with c0000005 (log 120: the DirectX redistributable's x64 helper, at its first kernel32 call). 0: as before.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_FEX_SMC_FASTPATH", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "madeira-bcd: smc-store-fastpath v1. MADEIRA_FEX_SMC_FASTPATH=0 restores the locked path.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_INVALIDATION_NESTED", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "MADEIRA: CodeInvalidationMutex is not recursive. When this thread already write-owns it, a second exclusive lock parks the thread behind itself, and every other thread queues behind it for good (log 56: one thread waiting on the lock it ...", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_IR_TOPO", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "iOS-Madeira ml599: name the pass that breaks the intrusive node list. DFE and RA both detect corruption at their own entry, but by then the damage is upstream and anonymous. This sweeps every block after every pass and reports the FIRST ...", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
        ConfigOption(key: "env.MADEIRA_IR_TOPO_MIN", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "ml599b: only sweep BIG functions. ml599 swept every block after every pass on every compile and that alone stalled the renderer -- it spent as much time in ValidateBlockTopology as in the whole x86 decoder, and Steam never reached the UI...", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
        ConfigOption(key: "env.MADEIRA_IRCAP_MODULE", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "ml623: arm the targeted IR capture (PassManager.cpp) once the module that owns the instruction under investigation is mapped. Module + RVA come from the environment so chasing a different miscompile never needs a rebuild; the defaults ar...", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_IRCAP_RVA", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "ml623: arm the targeted IR capture (PassManager.cpp) once the module that owns the instruction under investigation is mapped. Module + RVA come from the environment so chasing a different miscompile never needs a rebuild; the defaults ar...", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_NO_DFE", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "iOS-Madeira ml597: TARGETED A/B for the ml594 post-login hang. The renderer thread was sampled 9x at 97-100% CPU inside DeadFlagCalculationEliminination while everything else idled and Steam presented no further frames. FEX_O0 is the wro...", choices: [], sources: ["FEX/FEXCore/Source/Interface/IR/PassManager.cpp"]),
        ConfigOption(key: "env.MADEIRA_SMC_HOT_PAGE", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "MADEIRA: hot SMC pages (InvalidationTracker::EnableHotSMCPages). MADEIRA_SMC_HOT_PAGE: unset = 64 write faults within a second, 0 = off (every write to a code page invalidates it), N = threshold.", choices: [], sources: ["FEX/Source/Windows/ARM64EC/Module.cpp", "FEX/Source/Windows/WOW64/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_STRICT_SPLITLOCK", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "MADEIRA: StrictInProcessSplitLocks defaults ON for 32-bit guests. * An x86 LOCK op on a word that crosses a 16-byte boundary faults on this host and FEX emulates it as two separate half-width CASes. Without the strict mode two threads do...", choices: [], sources: ["FEX/Source/Windows/WOW64/Module.cpp"]),
        ConfigOption(key: "env.MADEIRA_WINEMONO_BRIDGE", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "FEX's Mono backpatcher bridge (ml712). On by itself for Wine Mono, 32- and 64-bit (ml1282/ml1286); for the 32-bit runtime in a guest window it also turns SMC detection off once the backpatcher is found (ml1280). 0 keeps it off.", choices: [], sources: ["FEX/Source/Windows/Common/InvalidationTracker.cpp"]),
        ConfigOption(key: "env.MADEIRA_WOW_SYSCALL_SWEEP", title: "", kind: .text, defaultValue: "", category: "x86 emulation (FEX)", note: "", choices: [], sources: ["FEX/Source/Windows/WOW64/Module.cpp"]),
        ConfigOption(key: "ignore-volatile-metadata", title: "FEX: x86 ordering for the whole image", kind: .bool, defaultValue: "0", category: "x86 emulation (FEX)", note: "Default off. 1: an x64 image's PE volatile metadata (MSVC /volatileMetadata) is cleared when it is mapped, so FEX orders every instruction of it by its TSO settings instead of only the listed ones. Slower; for testing memory-ordering bugs. Logged as [fex-vmeta]. Read at session start.", choices: [], sources: ["build/ntdll-unix/virtual_ios.c"]),
    ]
}
